// Cyrus mod categories: the middle branch of the web (Cyrus core -> game -> category -> mod).
// Deterministic keyword classifier over the build's own words (title, plugin name, tagline,
// summary, prompt); anything unmatched falls back to "Other". Pure, tested in test/cyrus.test.ts.

export type CyrusCategoryId = "worldgen" | "biomes" | "structures" | "gameplay" | "visuals" | "utility" | "other";

export type CyrusCategory = { id: CyrusCategoryId; name: string; icon: string; hue: string; words: RegExp };

/** Order = order on the web (left to right around the live game). Hues are the branch colours. */
export const CYRUS_CATEGORIES: CyrusCategory[] = [
  { id: "worldgen", name: "World Generation", icon: "tree", hue: "#3cf0c8", words: /\b(world ?gen|terrain|ores?|dimension|caves?|generat\w*|islands?|continents?|seed|mountains?|drops?|loot)\b/i },
  { id: "biomes", name: "Biomes", icon: "flower", hue: "#d94aff", words: /\b(biomes?|forests?|deserts?|jungle|swamp|weather|seasons?|flora|fauna|animals?|mobs?)\b/i },
  { id: "structures", name: "Structures", icon: "pickaxe", hue: "#2f7bff", words: /\b(structures?|villages?|dungeons?|towers?|castles?|houses?|buildings?|arenas?|zones?|regions?|claims?|protect\w*|grief)\b/i },
  { id: "gameplay", name: "Gameplay", icon: "gamecube", hue: "#ff3fd8", words: /\b(game|mini-?game|quests?|boss\w*|economy|coins?|shop|pay|pvp|combat|spleef|rewards?|streaks?|levels?|skills?|parkour|kits?|duels?)\b/i },
  { id: "visuals", name: "Visuals", icon: "visuals", hue: "#a42bff", words: /\b(scoreboards?|sidebar|particles?|titles?|hud|cosmetics?|colou?rs?|holograms?|tab ?list|nametags?|chat format|welcome|join messages?|display)\b/i },
  { id: "utility", name: "Utility", icon: "wrench", hue: "#2ee0f5", words: /\b(commands?|homes?|spawn|teleport\w*|tpa|heal|feed|admin|tools?|backpacks?|warps?|chat|messages?|msg|mute|permissions?|utility)\b/i },
  { id: "other", name: "Other", icon: "cube", hue: "#7a6bff", words: /$^/ },
];

export const cyrusCategory = (id: string) => CYRUS_CATEGORIES.find((c) => c.id === id) ?? CYRUS_CATEGORIES[CYRUS_CATEGORIES.length - 1];

/** Pick the category whose words appear most in the text (title words count double). */
export function classifyMod(parts: { title?: string | null; text?: string | null }): CyrusCategoryId {
  const title = parts.title || "";
  const text = parts.text || "";
  let best: CyrusCategoryId = "other", score = 0;
  for (const c of CYRUS_CATEGORIES) {
    if (c.id === "other") continue;
    const g = new RegExp(c.words.source, "gi");
    const n = (title.match(g)?.length ?? 0) * 2 + (text.match(g)?.length ?? 0);
    if (n > score) { score = n; best = c.id; }
  }
  return best;
}

/** Template category -> web category (templates fill empty branches, clearly marked). */
export const TEMPLATE_CATEGORY: Record<string, CyrusCategoryId> = { Gameplay: "gameplay", Economy: "gameplay", Social: "visuals", Admin: "utility", World: "worldgen" };
/**
 * The shared contract for per-game modding support in Cyrus (PURE, client-safe, data + types only).
 * Every supported game has ONE file `lib/cyrus/games/<gameId>.ts` default-exporting a `GameSupport`.
 * The studio, the install flow, the lifecycle warnings, the mod store and the marketing page all read
 * from it, so a fact is written once. Facts must be VERIFIED against the loader's own docs/source
 * (cite the URL in `sources`), never guessed. Where something could not be confirmed, say so in `unknowns`.
 */

/** Where a mod's files must be installed for it to work. */
export type InstallSide = "server" | "client" | "both";

export type GameVersionRule = {
  /** Game/server build the mod targets, as the loader labels it ("1.21.4", "v0.4.x", "Build 42"). */
  version: string;
  status: "current" | "supported" | "legacy" | "unsupported";
  /** Loader/framework version needed with this game version ("BepInEx 5.4.2200", "Oxide 2.0.x"). */
  loaderVersion?: string;
  /** What changed that breaks mods from the previous version (so we can warn). */
  breaking?: string[];
};

export type DangerousApi = {
  /** Regex source matched against generated code; a hit blocks the build or forces a warning. */
  pattern: string;
  severity: "block" | "warn";
  why: string;
};

export type GameSupport = {
  id: string;                    // matches CyrusGame.id in lib/cyrus/games.ts
  name: string;
  /** Plain-language one-liner of what Cyrus builds for this game. */
  builds: string;
  /** Language(s) the mod is written in and the runtime that loads it. */
  language: "Java" | "C#" | "Lua" | "C++" | "JSON/data";
  loader: { name: string; homepage: string; installDocs: string; licenseNote?: string };
  versions: GameVersionRule[];
  /** Where it installs. `reason` is shown to the customer in plain words ("players must also install this"). */
  install: {
    side: InstallSide;
    serverPath: string;          // relative to the game server root
    clientNote?: string;         // what a player must do on their own PC, if side is client/both
    needsRestart: boolean;
    hotReload: boolean;
    packaging: "jar" | "cs-source" | "dll" | "zip" | "lua-folder" | "pak";
    reason: string;
  };
  /** How Cyrus verifies output BEFORE the customer sees it. */
  verification: {
    method: "compile" | "static-lint" | "load-test" | "none";
    notes: string;
    /** Can we run it for real in a sandbox here, or only lint? Be honest. */
    canRunSandbox: boolean;
  };
  dangerousApis: DangerousApi[];
  /** Things that commonly break players' games/servers for this title, with how we avoid them. */
  breakageRisks: { risk: string; guard: string }[];
  /** How a mod becomes "out of date": what signal tells us (game patch, loader update, API removal). */
  outdatedSignals: { signal: string; source: string }[];
  /** Mod categories this game's engine can actually express (ids from lib/cyrus/categories.ts universal set). */
  categories: string[];
  /** Concrete example prompts that work well, for the starter chips. */
  examplePrompts: string[];
  sources: string[];             // URLs verified while writing this file
  unknowns: string[];            // honest list of anything not confirmed
};
import type { ModBuildView } from "../modbuilder/types";

export type ModelId = "katara" | "saka" | "yakko";

export type CategoryKey =
  | "weapons"
  | "creatures"
  | "worlds"
  | "mechanics"
  | "shaders"
  | "magic"
  | "quests"
  | "interface"
  | "audio"
  | "vehicles"
  | "items"
  | "characters";

/** Built-in ids are "minecraft", "palworld", "rust", "valheim", "zomboid", "terraria"; user-added games get "custom-…" ids. */
export type GameId = string;

/** Which code generator a game's mods are written with. */
export type TemplateKey = "fabric" | "papyrus" | "smapi" | "tmodloader" | "cet" | "oxide" | "bepinex" | "zomboid" | "ue4ss";

export type EmblemKey = "cube" | "dragon" | "sprout" | "tree" | "chip";

export interface Game {
  id: GameId;
  name: string;
  /** Short label used where space is tight. */
  short: string;
  /** Mod toolchain, e.g. "Fabric · Java 21". */
  toolchain: string;
  language: CodeLanguage;
  /** Neon accent used for the branch, as an "r g b" triple. */
  rgb: string;
  emblem: EmblemKey;
  /** The game's real logo (a file under /public), shown instead of the emblem where present. */
  logo?: string;
  /** "light" for white artwork, which gets inked dark on the light theme. */
  logoTone?: "light";
  blurb: string;
  aliases: string[];
  categories: CategoryKey[];
  template: TemplateKey;
  /** Added by the user from the "Add game" dialog. */
  custom?: boolean;
  /** Nxeon: Cyrus really builds for this game (the build service compiles it). The others are
   *  template previews until a real builder exists. */
  real?: boolean;
}

export interface CategoryMeta {
  key: CategoryKey;
  label: string;
  rgb: string;
  description: string;
  keywords: string[];
}

export type CodeLanguage = "java" | "papyrus" | "csharp" | "lua" | "glsl" | "json" | "markdown" | "xml" | "toml" | "text";

export interface ModFile {
  path: string;
  language: CodeLanguage;
  content: string;
}

export interface ModVersion {
  id: string;
  label: string;
  createdAt: number;
  model: ModelId;
  credits: number;
  prompt: string;
  summary: string;
  files: ModFile[];
  additions: number;
  deletions: number;
  /** Nxeon: the real build behind this version (files load from the build service on demand). */
  real?: RealVersion;
}

export interface RealVersion {
  buildId: string;
  status: string;
  mcVersion: string;
  jarName: string | null;
  jarSize: number | null;
  error: string | null;
  attempts: number;
  durationMs: number | null;
  /** Source files the build produced (paths + sizes); contents are fetched lazily. */
  paths: { path: string; size: number }[];
}

export interface Mod {
  id: string;
  gameId: GameId;
  category: CategoryKey;
  name: string;
  summary: string;
  createdAt: number;
  tags: string[];
  /** Seed mods have their files built lazily from the engine templates. */
  seed?: boolean;
  versions: ModVersion[];
  activeVersionId?: string;
  /** Nxeon: a starter idea on a real game's branch. Clicking it writes the prompt, nothing is built yet. */
  idea?: boolean;
  ideaPrompt?: string;
  /** Nxeon: a real project (ModBuild rows grouped by root). */
  real?: { rootId: string; running: boolean; failed: boolean; headBuildId: string | null; favourite: boolean };
}

export interface ModelMeta {
  id: ModelId;
  name: string;
  credits: number;
  tagline: string;
  description: string;
  rgb: string;
  /** Visual pacing for the simulated stream. */
  chunk: [number, number];
  tick: number;
}

export type Level = "core" | "game" | "category" | "mod";

export interface Selection {
  level: Level;
  gameId?: GameId;
  category?: CategoryKey;
  modId?: string;
}

/** Events streamed from /api/cyrus/generate as NDJSON lines. Nxeon adds `build` (the real build
 *  behind a Minecraft forge), `file-set` (replace a file's content: the builder edited it in
 *  place) and `ping` (keep-alive while the compiler runs). Clients ignore types they don't know. */
export type GenEvent =
  | { type: "start"; jobId: string; model: ModelId; credits: number; real?: boolean }
  | { type: "build"; build: ModBuildView }
  | { type: "file-set"; path: string; content: string }
  | { type: "ping" }
  | { type: "route"; gameId: GameId; category: CategoryKey; modName: string; modId: string; summary: string; tags: string[] }
  | { type: "think"; id: string; label: string; detail?: string }
  | { type: "think-done"; id: string }
  | { type: "file"; path: string; language: CodeLanguage }
  | { type: "chunk"; path: string; text: string }
  | { type: "file-done"; path: string }
  | { type: "done"; summary: string; notes: string; tokens?: number }
  | { type: "error"; message: string };
// Cyrus game registry (client-safe, data only). Adding a game = adding a row here; the home
// game selector, the version picker and the copy all read from it. No official logos or art:
// each game gets a neutral two-letter text mark.
import { MB_VERSIONS, MB_DEFAULT_VERSION } from "../modbuilder/types";

export type CyrusGameStatus = "live" | "soon";

export type CyrusGame = {
  id: string;
  name: string;
  status: CyrusGameStatus;
  /** two-letter text mark drawn in a neutral tile */
  mark: string;
  /** what Cyrus builds for it, customer voice */
  builds: string;
  /** server software the mods target (shown next to the version) */
  loader: string;
  /** supported server versions, newest first */
  versions: readonly string[];
  defaultVersion?: string;
  /** legacy flag, true when status === "live" */
  available: boolean;
  note: string;
};

const g = (x: Omit<CyrusGame, "available" | "note">): CyrusGame => ({ ...x, available: x.status === "live", note: x.status === "live" ? x.builds : "Coming soon" });

export const CYRUS_GAMES: CyrusGame[] = [
  g({ id: "minecraft", name: "Minecraft", status: "live", mark: "MC", builds: "Paper and Purpur server plugins", loader: "Paper", versions: MB_VERSIONS, defaultVersion: MB_DEFAULT_VERSION }),
  g({ id: "ark", name: "ARK", status: "soon", mark: "AR", builds: "ARK: Survival Ascended server mods", loader: "ASA", versions: [] }),
  g({ id: "theisle", name: "The Isle", status: "soon", mark: "TI", builds: "The Isle Evrima server mods", loader: "Evrima", versions: [] }),
  g({ id: "palworld", name: "Palworld", status: "soon", mark: "PW", builds: "UE4SS server mods", loader: "UE4SS", versions: [] }),
  g({ id: "rust", name: "Rust", status: "soon", mark: "RS", builds: "Oxide / Carbon plugins", loader: "Oxide", versions: [] }),
  g({ id: "valheim", name: "Valheim", status: "soon", mark: "VH", builds: "BepInEx server mods", loader: "BepInEx", versions: [] }),
];

export const CYRUS_DEFAULT_GAME = CYRUS_GAMES.find((x) => x.status === "live")!;
export const cyrusGame = (id: string | null | undefined) => CYRUS_GAMES.find((x) => x.id === id) ?? CYRUS_DEFAULT_GAME;
/** "1.20.4 – 1.21.11" */
export const versionRange = (game: CyrusGame) => (game.versions.length ? (game.versions.length > 1 ? `${game.versions[game.versions.length - 1]} – ${game.versions[0]}` : game.versions[0]) : "");

"use client";

import { useMemo } from "react";
import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";
import { MB_DEFAULT_VERSION, type ModBuildView } from "../modbuilder/types";
import type { MbServer } from "../modbuilder/install";
import { GAMES, GAME_BY_ID, SEED_MODS, categoryNodeId } from "./data";
import { seedVersions } from "./engine";
import { deriveReal, isRealModId, rootOfRealMod, toModFile, type RealModel } from "./real";
import type { CategoryKey, Game, GameId, Mod, ModelId, ModFile, ModVersion, Selection } from "./types";

// Nxeon (Cyrus v5): the handoff's local store, with the REAL account behind it.
//  - Minecraft projects are the account's builds (`real`, derived from ModBuild rows by
//    lib/cyrus/real.ts); their notes / restore / favourite are saved to the DB, their files load
//    from the build service. Nothing about them is kept in localStorage.
//  - Template games (everything Cyrus doesn't compile yet) keep the handoff's local mods,
//    persisted per account (`cyrus-state-v1:<userId>`).
//  - There is no local credit counter: tokens are the real economy (components/cyrus-tokens).
//  - The theme is the PORTAL's (html[data-theme], localStorage "nx-theme"); `theme` here only
//    mirrors it so the canvas/shaders can read it.
const EMPTY_REAL: RealModel = { projects: [], mods: [], versions: {}, active: {}, notes: {}, aiNotes: {} };
const REAL_GAME = GAMES.find((g) => g.real) ?? GAMES[0];
const noteTimers = new Map<string, number>();

export type PanelTab = "code" | "files" | "versions" | "notes";
export type Theme = "dark" | "light";

export interface ThinkItem {
  id: string;
  label: string;
  detail?: string;
  done: boolean;
  startedAt: number;
  endedAt?: number;
}

export type JobStatus = "connecting" | "thinking" | "writing" | "done" | "error" | "cancelled";

export interface Job {
  id: string;
  status: JobStatus;
  prompt: string;
  model: ModelId;
  images: string[];
  credits: number;
  refining: boolean;
  version: number;
  gameId?: GameId;
  category?: CategoryKey;
  modId?: string;
  modName?: string;
  steps: ThinkItem[];
  files: ModFile[];
  activeFile?: string;
  startedAt: number;
  finishedAt?: number;
  error?: string;
  /** Nxeon: the real build behind this forge (Minecraft), and the tokens it holds while it runs. */
  buildId?: string;
  real?: boolean;
}

export interface Toast {
  id: string;
  title: string;
  body?: string;
  tone: "info" | "success" | "error";
  rgb?: string;
}

export interface FocusTarget {
  kind: "overview" | "node" | "path";
  id?: string;
  tick: number;
}

interface CyrusState {
  theme: Theme;
  userMods: Mod[];
  userVersions: Record<string, ModVersion[]>;
  activeVersion: Record<string, string>;
  notes: Record<string, string>;
  aiNotes: Record<string, string>;
  model: ModelId;
  /** Nxeon: the Paper version real Minecraft builds target. */
  mcVersion: string;
  setMcVersion: (v: string) => void;
  /** Branch positions the user dragged, as offsets from each node's parent. Survives reloads. */
  layout: Record<string, [number, number]>;
  /** Game branches the user added themselves. */
  customGames: Game[];
  /** Which core concept renders at the centre of the network (see components/cosmos/cores). */
  coreStyle: string;
  addGameOpen: boolean;

  selection: Selection;
  focus: FocusTarget;
  panelOpen: boolean;
  panelTab: PanelTab;
  activeFile: string | null;
  navOpen: boolean;
  paletteOpen: boolean;
  job: Job | null;
  toasts: Toast[];
  promptFocusTick: number;
  /** A prompt to write into the dock (starter ideas on a real game's branch). */
  prefill: { text: string; tick: number } | null;

  /* Nxeon: the real account (never persisted locally). */
  userId: string | null;
  realBuilds: ModBuildView[];
  real: RealModel;
  /** Source files of real builds, loaded on demand, by build id. */
  realFiles: Record<string, ModFile[] | "loading" | "error">;
  servers: MbServer[];
  online: boolean;
  setReal: (builds: ModBuildView[]) => void;
  upsertReal: (builds: ModBuildView[]) => void;
  refreshReal: () => Promise<void>;
  loadRealFiles: (buildId: string, paths: string[], opts?: { force?: boolean }) => Promise<void>;
  seedRealFiles: (buildId: string, files: ModFile[]) => void;
  patchProject: (rootId: string, patch: Record<string, unknown>) => Promise<string | null>;
  pickIdea: (modId: string) => void;

  setTheme: (t: Theme) => void;
  toggleTheme: () => void;
  select: (sel: Selection, opts?: { openPanel?: boolean; focus?: FocusTarget["kind"] }) => void;
  goUp: () => void;
  setModel: (m: ModelId) => void;
  setPanelOpen: (open: boolean) => void;
  setPanelTab: (tab: PanelTab) => void;
  setActiveFile: (path: string | null) => void;
  setNavOpen: (open: boolean) => void;
  setPaletteOpen: (open: boolean) => void;
  recenter: () => void;
  toast: (t: Omit<Toast, "id">) => void;
  dismissToast: (id: string) => void;
  setNote: (modId: string, text: string) => void;
  restoreVersion: (modId: string, versionId: string) => void;
  focusPrompt: () => void;
  setNodeHome: (id: string, hx: number, hy: number) => void;
  resetLayout: () => void;
  setAddGameOpen: (open: boolean) => void;
  addGame: (game: Game) => void;
  removeGame: (id: string) => void;
  setCoreStyle: (id: string) => void;
}

export const CORE_ID = "core";

export const useStore = create<CyrusState>()(
  persist(
    (set, get) => ({
      theme: "dark",
      userMods: [],
      userVersions: {},
      activeVersion: {},
      notes: {},
      aiNotes: {},
      model: "katara",
      mcVersion: MB_DEFAULT_VERSION,
      setMcVersion: (mcVersion) => set({ mcVersion }),
      layout: {},
      customGames: [],
      addGameOpen: false,
      coreStyle: "particles",

      selection: { level: "core" },
      focus: { kind: "overview", tick: 0 },
      panelOpen: false,
      panelTab: "code",
      activeFile: null,
      navOpen: false,
      paletteOpen: false,
      job: null,
      toasts: [],
      promptFocusTick: 0,
      prefill: null,

      userId: null,
      realBuilds: [],
      real: EMPTY_REAL,
      realFiles: {},
      servers: [],
      online: true,
      setReal: (builds) => set({ realBuilds: builds, real: deriveReal(builds, REAL_GAME) }),
      upsertReal: (list) => {
        const m = new Map(get().realBuilds.map((b) => [b.id, b]));
        for (const b of list) m.set(b.id, { ...m.get(b.id), ...b });
        get().setReal([...m.values()]);
      },
      refreshReal: async () => {
        const r = await fetch("/api/mod-builder/builds", { cache: "no-store" }).catch(() => null);
        if (!r?.ok) return;
        const j = (await r.json().catch(() => null)) as { builds?: ModBuildView[] } | null;
        if (j?.builds) get().upsertReal(j.builds);
      },
      loadRealFiles: async (buildId, paths, opts) => {
        const cur = get().realFiles[buildId];
        if (!opts?.force && (cur === "loading" || Array.isArray(cur))) return;
        if (!Array.isArray(cur)) set((s) => ({ realFiles: { ...s.realFiles, [buildId]: "loading" } }));
        const files = await Promise.all(
          paths.map(async (path) => {
            const r = await fetch(`/api/mod-builder/builds/${buildId}/source?path=${encodeURIComponent(path)}`).catch(() => null);
            return r?.ok ? toModFile(path, await r.text()) : null;
          }),
        );
        const ok = files.filter((f): f is ModFile => !!f);
        set((s) => ({ realFiles: { ...s.realFiles, [buildId]: ok.length || !paths.length ? ok : "error" } }));
      },
      seedRealFiles: (buildId, files) => set((s) => ({ realFiles: { ...s.realFiles, [buildId]: files } })),
      patchProject: async (rootId, patch) => {
        // optimistic: the project's meta lives on its root build
        const apply = (builds: ModBuildView[]) =>
          builds.map((b) => (b.id === rootId ? { ...b, cyrus: { ...((b.cyrus as object) ?? {}), ...patch } } : b));
        get().setReal(apply(get().realBuilds));
        try {
          const r = await fetch(`/api/mod-builder/projects/${rootId}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(patch) });
          const j = await r.json().catch(() => ({}));
          if (!r.ok) {
            void get().refreshReal();
            return (j as { error?: string }).error || "Couldn't save.";
          }
          get().setReal(get().realBuilds.map((b) => (b.id === rootId ? { ...b, cyrus: (j as { meta?: unknown }).meta ?? b.cyrus } : b)));
          return null;
        } catch {
          return "Couldn't save.";
        }
      },
      pickIdea: (modId) => {
        const mod = findMod(modId);
        if (!mod?.ideaPrompt) return;
        get().select({ level: "category", gameId: mod.gameId, category: mod.category });
        set((s) => ({ prefill: { text: mod.ideaPrompt!, tick: (s.prefill?.tick ?? 0) + 1 } }));
      },

      setTheme: (theme) => {
        // The portal owns the theme. Press its own toggle (top bar) so its icon, its transition
        // and its saved choice ("nx-theme") all stay in step; CyrusApp mirrors data-theme back.
        const current = document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark";
        if (current === theme) return;
        const portal = document.querySelector<HTMLButtonElement>("button.nx-theme-toggle");
        if (portal) { portal.click(); return; }
        try { localStorage.setItem("nx-theme", theme); } catch { /* private mode */ }
        if (theme === "light") document.documentElement.setAttribute("data-theme", "light");
        else document.documentElement.removeAttribute("data-theme");
        set({ theme });
      },
      toggleTheme: () => get().setTheme(get().theme === "dark" ? "light" : "dark"),

      select: (sel, opts) => {
        const focusKind = opts?.focus ?? (sel.level === "core" ? "overview" : "node");
        const id =
          sel.level === "mod"
            ? sel.modId
            : sel.level === "category"
              ? `${sel.gameId}:${sel.category}`
              : sel.level === "game"
                ? sel.gameId
                : CORE_ID;
        set((s) => ({
          selection: sel,
          focus: { kind: focusKind, id, tick: s.focus.tick + 1 },
          panelOpen: opts?.openPanel ?? (sel.level === "mod" ? true : s.panelOpen),
          activeFile: sel.level === "mod" && sel.modId !== s.selection.modId ? null : s.activeFile,
        }));
      },

      goUp: () => {
        const { selection, select } = get();
        if (selection.level === "mod") select({ level: "category", gameId: selection.gameId, category: selection.category });
        else if (selection.level === "category") select({ level: "game", gameId: selection.gameId });
        else select({ level: "core" });
      },

      setModel: (model) => set({ model }),
      setPanelOpen: (panelOpen) => set({ panelOpen }),
      setPanelTab: (panelTab) => set({ panelTab, panelOpen: true }),
      setActiveFile: (activeFile) => set({ activeFile }),
      setNavOpen: (navOpen) => set({ navOpen }),
      setPaletteOpen: (paletteOpen) => set({ paletteOpen }),
      recenter: () => set((s) => ({ focus: { kind: "overview", tick: s.focus.tick + 1 } })),

      toast: (t) => {
        const id = Math.random().toString(36).slice(2);
        set((s) => ({ toasts: [...s.toasts.slice(-3), { ...t, id }] }));
        window.setTimeout(() => get().dismissToast(id), t.tone === "error" ? 6000 : 4200);
      },
      dismissToast: (id) => set((s) => ({ toasts: s.toasts.filter((t) => t.id !== id) })),

      setNote: (modId, text) => {
        if (isRealModId(modId)) {
          // saved on the project (DB), debounced
          set((s) => ({ real: { ...s.real, notes: { ...s.real.notes, [modId]: text } } }));
          window.clearTimeout(noteTimers.get(modId));
          noteTimers.set(modId, window.setTimeout(() => void get().patchProject(rootOfRealMod(modId), { notes: text }), 700));
          return;
        }
        set((s) => ({ notes: { ...s.notes, [modId]: text } }));
      },
      restoreVersion: (modId, versionId) => {
        if (isRealModId(modId)) {
          const v = get().real.versions[modId]?.find((x) => x.id === versionId);
          if (v?.real?.status !== "succeeded") {
            get().toast({ tone: "error", title: "Can't restore this version", body: "Only versions that built can be made current." });
            return;
          }
          void get().patchProject(rootOfRealMod(modId), { headBuildId: versionId }).then((e) => {
            if (e) get().toast({ tone: "error", title: "Couldn't restore", body: e });
          });
          return;
        }
        set((s) => ({ activeVersion: { ...s.activeVersion, [modId]: versionId } }));
      },
      focusPrompt: () => set((s) => ({ promptFocusTick: s.promptFocusTick + 1 })),
      setNodeHome: (id, hx, hy) => set((s) => ({ layout: { ...s.layout, [id]: [Math.round(hx), Math.round(hy)] } })),
      resetLayout: () => set({ layout: {} }),
      setAddGameOpen: (addGameOpen) => set({ addGameOpen }),
      setCoreStyle: (coreStyle) => set({ coreStyle }),
      addGame: (game) => set((s) => ({ customGames: [...s.customGames, { ...game, custom: true }] })),
      removeGame: (id) =>
        set((s) => {
          const game = s.customGames.find((g) => g.id === id);
          if (!game) return {};
          const gone = new Set(s.userMods.filter((m) => m.gameId === id).map((m) => m.id));
          const layout = { ...s.layout };
          delete layout[id];
          for (const key of game.categories) delete layout[categoryNodeId(id, key)];
          const strip = <T,>(rec: Record<string, T>) => Object.fromEntries(Object.entries(rec).filter(([k]) => !gone.has(k)));
          return {
            customGames: s.customGames.filter((g) => g.id !== id),
            userMods: s.userMods.filter((m) => m.gameId !== id),
            userVersions: strip(s.userVersions),
            activeVersion: strip(s.activeVersion),
            notes: strip(s.notes),
            aiNotes: strip(s.aiNotes),
            layout,
            selection: s.selection.gameId === id ? ({ level: "core" } as Selection) : s.selection,
          };
        }),
    }),
    {
      name: "cyrus-state-v1",
      storage: createJSONStorage(() => localStorage),
      skipHydration: true,
      partialize: (s) => ({
        userMods: s.userMods,
        userVersions: s.userVersions,
        activeVersion: s.activeVersion,
        notes: s.notes,
        aiNotes: s.aiNotes,
        model: s.model,
        mcVersion: s.mcVersion,
        layout: s.layout,
        customGames: s.customGames,
        coreStyle: s.coreStyle,
      }),
    },
  ),
);

/* ───────────── Derived helpers ───────────── */

/** Built-in or user-added game by id. */
export function getGame(id: GameId | undefined): Game | undefined {
  if (!id) return undefined;
  return GAME_BY_ID[id] ?? useStore.getState().customGames.find((g) => g.id === id);
}

export function useGames(): Game[] {
  const custom = useStore((s) => s.customGames);
  return useMemo(() => [...GAMES, ...custom], [custom]);
}

export function useGame(id: GameId | undefined): Game | undefined {
  const games = useGames();
  return useMemo(() => (id ? games.find((g) => g.id === id) : undefined), [games, id]);
}

const seedCache = new Map<string, ModVersion[]>();

/** Real versions carry their loaded files (empty until loadRealFiles has them). */
function withRealFiles(list: ModVersion[] | undefined, files: CyrusState["realFiles"]): ModVersion[] {
  return (list ?? []).map((v) => {
    const f = v.real ? files[v.real.buildId] : undefined;
    return Array.isArray(f) ? { ...v, files: f } : v;
  });
}

export function versionsOf(mod: Mod | undefined, userVersions: Record<string, ModVersion[]>): ModVersion[] {
  if (!mod) return [];
  if (mod.real) {
    const s = useStore.getState();
    return withRealFiles(s.real.versions[mod.id], s.realFiles);
  }
  let base: ModVersion[] = [];
  if (mod.seed) {
    base = seedCache.get(mod.id) ?? seedVersions(mod);
    seedCache.set(mod.id, base);
  }
  return [...base, ...(userVersions[mod.id] ?? [])];
}

/** Pills a category shows before "+N more" (components/cyrus/cosmos/graph.ts VISIBLE_MODS). */
const VISIBLE = 3;

/** Seeds + the account's real projects + local template mods. Ideas on a real game only fill
 *  the room the real projects leave in their category, so they never push a real mod off. */
export function combineMods(realMods: Mod[], userMods: Mod[]): Mod[] {
  const realPer = new Map<string, number>();
  for (const m of realMods) realPer.set(`${m.gameId}:${m.category}`, (realPer.get(`${m.gameId}:${m.category}`) ?? 0) + 1);
  const ideaPer = new Map<string, number>();
  const seeds = SEED_MODS.filter((m) => {
    if (!m.idea) return true;
    const k = `${m.gameId}:${m.category}`;
    const n = ideaPer.get(k) ?? 0;
    if (n + (realPer.get(k) ?? 0) >= VISIBLE) return false;
    ideaPer.set(k, n + 1);
    return true;
  });
  return [...seeds, ...realMods, ...userMods];
}

export function useAllMods(): Mod[] {
  const userMods = useStore((s) => s.userMods);
  const realMods = useStore((s) => s.real.mods);
  return useMemo(() => combineMods(realMods, userMods), [realMods, userMods]);
}

export function findMod(id: string | undefined): Mod | undefined {
  if (!id) return undefined;
  const s = useStore.getState();
  return SEED_MODS.find((m) => m.id === id) ?? s.real.mods.find((m) => m.id === id) ?? s.userMods.find((m) => m.id === id);
}

export function useMod(id: string | undefined) {
  const userMods = useStore((s) => s.userMods);
  const realMods = useStore((s) => s.real.mods);
  return useMemo(
    () => (id ? (SEED_MODS.find((m) => m.id === id) ?? realMods.find((m) => m.id === id) ?? userMods.find((m) => m.id === id)) : undefined),
    [id, userMods, realMods],
  );
}

export function useModVersions(mod: Mod | undefined) {
  const userVersions = useStore((s) => s.userVersions);
  const activeVersion = useStore((s) => s.activeVersion);
  const real = useStore((s) => s.real);
  const realFiles = useStore((s) => s.realFiles);
  return useMemo(() => {
    const versions = mod?.real ? withRealFiles(real.versions[mod.id], realFiles) : versionsOf(mod, userVersions);
    const activeMap = mod?.real ? real.active : activeVersion;
    const activeId = mod ? (activeMap[mod.id] ?? versions[versions.length - 1]?.id) : undefined;
    const active = versions.find((v) => v.id === activeId) ?? versions[versions.length - 1];
    return { versions, active };
  }, [mod, userVersions, activeVersion, real, realFiles]);
}

/** Notes for any mod: the DB-backed ones for real projects, local ones otherwise. */
export function useModNotes(modId: string): { mine: string; cyrus: string | undefined } {
  const mine = useStore((s) => (isRealModId(modId) ? s.real.notes[modId] : s.notes[modId]) ?? "");
  const cyrus = useStore((s) => (isRealModId(modId) ? s.real.aiNotes[modId] : s.aiNotes[modId]));
  return { mine, cyrus };
}

export { isRealModId };

export const isJobLive = (job: Job | null) =>
  !!job && (job.status === "connecting" || job.status === "thinking" || job.status === "writing");

