interface Attachment {
  id: string;
  url: string;
  name: string;
  /** Nxeon: the image uploaded for real builds (/api/mod-builder/uploads); Cyrus looks at it while it plans. */
  uploadId?: string;
  state: "up" | "ok" | "err";
}

/** Upload a reference image so a real build can read it (same endpoint and limits as v4). */
async function uploadImage(f: File): Promise<string | null> {
  if (!/^image\/(png|jpe?g|webp|gif)$/.test(f.type) || f.size > 5 * 1024 * 1024) return null;
  const fd = new FormData();
  fd.append("file", f, f.name || "pasted.png");
  const r = await fetch("/api/mod-builder/uploads", { method: "POST", body: fd }).catch(() => null);
  const j = r?.ok ? ((await r.json().catch(() => null)) as { upload?: { id: string } } | null) : null;
  return j?.upload?.id ?? null;
}

export function PromptDock() {
  const [text, setText] = useState("");
  const [images, setImages] = useState<Attachment[]>([]);
  const [focused, setFocused] = useState(false);
  const [typing, setTyping] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const taRef = useRef<HTMLTextAreaElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const typingTimer = useRef(0);
  const typeInTimer = useRef(0);
  const voiceBase = useRef("");

  const job = useStore((s) => s.job);
  const live = isJobLive(job);
  const selection = useStore((s) => s.selection);
  const model = MODEL_BY_ID[useStore((s) => s.model)];
  const customGames = useStore((s) => s.customGames);
  const mcVersion = useStore((s) => s.mcVersion);
  const setMcVersion = useStore((s) => s.setMcVersion);
  const prefill = useStore((s) => s.prefill);
  const select = useStore((s) => s.select);
  const promptFocusTick = useStore((s) => s.promptFocusTick);
  const panelOpen = useStore((s) => s.panelOpen);
  const mod = useMod(selection.level === "mod" ? selection.modId : undefined);
  const { versions } = useModVersions(mod);

  useEffect(() => {
    if (promptFocusTick) taRef.current?.focus();
  }, [promptFocusTick]);

  // Auto-grow the textarea.
  useLayoutEffect(() => {
    const ta = taRef.current;
    if (!ta) return;
    ta.style.height = "0px";
    ta.style.height = `${Math.min(ta.scrollHeight, 180)}px`;
  }, [text]);

  const pulseTyping = useCallback(() => {
    setTyping(true);
    window.clearTimeout(typingTimer.current);
    typingTimer.current = window.setTimeout(() => setTyping(false), 1100);
  }, []);

  const addFiles = useCallback((files: File[]) => {
    const imgs = files.filter((f) => f.type.startsWith("image/")).slice(0, 4);
    if (!imgs.length) return;
    const added = imgs.map((f) => ({ f, a: { id: Math.random().toString(36).slice(2), url: URL.createObjectURL(f), name: f.name || "pasted image", state: "up" as const } }));
    setImages((prev) => [...prev, ...added.map((x) => x.a)].slice(0, 4));
    for (const { f, a } of added) {
      void uploadImage(f).then((uploadId) =>
        setImages((cur) => cur.map((i) => (i.id === a.id ? { ...i, uploadId: uploadId ?? undefined, state: uploadId ? "ok" : "err" } : i))),
      );
    }
    fx.keystroke(1.5);
  }, []);

  const onPaste = (e: ClipboardEvent<HTMLTextAreaElement>) => {
    const files = Array.from(e.clipboardData.items)
      .filter((i) => i.kind === "file" && i.type.startsWith("image/"))
      .map((i) => i.getAsFile())
      .filter((f): f is File => !!f);
    if (files.length) {
      e.preventDefault();
      addFiles(files);
    }
  };

  const onDrop = (e: DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    addFiles(Array.from(e.dataTransfer.files));
  };

  const removeImage = (id: string) =>
    setImages((prev) => {
      const hit = prev.find((i) => i.id === id);
      if (hit) URL.revokeObjectURL(hit.url);
      return prev.filter((i) => i.id !== id);
    });

  const submit = () => {
    if (live || !text.trim()) return;
    window.clearInterval(typeInTimer.current);
    forge(text, images.map((i) => ({ url: i.url, uploadId: i.uploadId })));
    setText("");
    setImages([]);
  };

  // Starter ideas type themselves in — which also charges the core.
  const pickIdea = (idea: StarterIdea) => {
    if (live) return;
    window.clearInterval(typeInTimer.current);
    select({ level: "category", gameId: idea.gameId, category: idea.category });
    let i = 0;
    setText("");
    typeInTimer.current = window.setInterval(() => {
      i = Math.min(idea.prompt.length, i + 2 + Math.floor(Math.random() * 2));
      setText(idea.prompt.slice(0, i));
      fx.keystroke(0.3);
      pulseTyping();
      if (i >= idea.prompt.length) {
        window.clearInterval(typeInTimer.current);
        taRef.current?.focus();
      }
    }, 22);
  };

  useEffect(() => () => window.clearInterval(typeInTimer.current), []);

  // An idea pill on a real game's branch writes its prompt here (store.pickIdea), typed in like a starter idea.
  useEffect(() => {
    if (!prefill || live) return;
    window.clearInterval(typeInTimer.current);
    let i = 0;
    setText("");
    typeInTimer.current = window.setInterval(() => {
      i = Math.min(prefill.text.length, i + 3 + Math.floor(Math.random() * 2));
      setText(prefill.text.slice(0, i));
      fx.keystroke(0.3);
      pulseTyping();
      if (i >= prefill.text.length) {
        window.clearInterval(typeInTimer.current);
        taRef.current?.focus();
      }
    }, 18);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [prefill?.tick]);

  // Context: where in the network this prompt will land.
  const game = useGame(selection.gameId);
  const cat = selection.category ? CATEGORY_BY_KEY[selection.category] : undefined;
  const placeholder =
    selection.level === "mod" && mod
      ? `Refine ${mod.name} — e.g. "add a charged special attack"`
      : cat && game
        ? `Describe a ${game.short} ${cat.label.toLowerCase().replace(/s$/, "")} mod…`
        : game
          ? `Describe a ${game.name} mod…`
          : "Describe a mod — Cyrus routes it to the right game and category…";

  // Nxeon: will this forge be a REAL build (Minecraft: tokens, a real plugin) or a template preview?
  const realTarget = (() => {
    if (selection.level === "mod" && mod) return !!mod.real || !!mod.idea || !!game?.real;
    const t = text.trim();
    if (!t) return !!game?.real || selection.level === "core";
    const r = routePrompt(t, { gameId: selection.gameId, category: selection.category }, [...GAMES, ...customGames]);
    return !!GAMES.find((g) => g.id === r.gameId)?.real;
  })();
  const uploading = images.some((i) => i.state === "up");
  const sendable = !!text.trim() && !live && !uploading;
  const wide = useMediaQuery("(min-width: 1024px)");
  const dockStyle =
    panelOpen && wide
      ? // Nxeon: the studio is narrower than a full window (portal rail), so the dock also
        // shrinks to the space left of the panel instead of sliding under it.
        { left: "calc((100cqw - min(560px, 40cqw)) / 2)", width: "min(780px, calc(100cqw - min(560px, 40cqw) - 32px))" }
      : undefined;

  return (
    <div
      className="fixed bottom-4 left-1/2 z-30 w-[min(780px,calc(100cqw-24px))] -translate-x-1/2 transition-[left] duration-500 ease-[var(--ease-out-expo)] md:bottom-6"
      style={dockStyle}
    >
      <ThinkingTrace />

      <div
        className="prompt-shell"
        data-active={focused || typing ? "true" : "false"}
        data-busy={live ? "true" : "false"}
        onDragOver={(e) => {
          if (Array.from(e.dataTransfer.types).includes("Files")) {
            e.preventDefault();
            setDragOver(true);
          }
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={onDrop}
      >
        <div className="cy5-glass relative rounded-[24px] !border-transparent">
          {dragOver && (
            <div className="absolute inset-1.5 z-10 grid place-items-center rounded-[20px] border border-dashed border-cy-accent/60 bg-[rgb(var(--glow)/0.1)] text-[13px] font-medium text-cy-accent-ink backdrop-blur-sm">
              Drop images to give Cyrus a reference
            </div>
          )}

          {/* Context chip */}
          <div className="flex items-center gap-2 px-4 pt-3">
            {selection.level === "core" ? (
              <span className="inline-flex items-center gap-1.5 rounded-full bg-[rgb(var(--glow)/0.1)] px-2.5 py-1 text-[11px] font-medium text-cy-accent-ink">
                <SparkleIcon /> Auto-route through the core
              </span>
            ) : (
              <span
                className="tint inline-flex max-w-full items-center gap-1.5 truncate rounded-full py-1 pl-1.5 pr-1 text-[11px] font-medium text-cy-ink-2"
                style={{ ["--c" as string]: (cat ?? game)!.rgb, background: `rgb(${(cat ?? game)!.rgb} / 0.12)` }}
              >
                <span className="text-[13px]" style={{ color: "var(--cc)" }}>
                  {cat ? <CategoryIcon k={cat.key} /> : game && <GameEmblem emblem={game.emblem} logo={game.logo} logoTone={game.logoTone} />}
                </span>
                {selection.level === "mod" && mod ? (
                  <span className="truncate">
                    Refining <b className="font-semibold text-cy-ink">{mod.name}</b> → v{versions.length + 1}
                  </span>
                ) : (
                  <span className="truncate">
                    {game?.short}
                    {cat && <> › {cat.label}</>}
                  </span>
                )}
                <button
                  type="button"
                  aria-label="Clear context"
                  onClick={() => select({ level: "core" })}
                  className="ml-0.5 grid h-4 w-4 place-items-center rounded-full text-[9px] text-cy-muted hover:bg-[rgb(var(--glow)/0.15)] hover:text-cy-ink"
                >
                  <CloseIcon />
                </button>
              </span>
            )}
          </div>

          {/* Pasted images */}
          {images.length > 0 && (
            <div className="flex gap-2 overflow-x-auto px-4 pt-2.5">
              {images.map((img) => (
                <div key={img.id} className="animate-pop group relative h-16 w-16 shrink-0 overflow-hidden rounded-xl border border-cy-line-2">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img src={img.url} alt={img.name} className="h-full w-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent" />
                  {img.state !== "ok" && (
                    <span className="absolute inset-x-0 bottom-0 bg-black/55 py-0.5 text-center text-[9px] font-medium text-white" title={img.state === "err" ? "Couldn't upload: Cyrus won't see this image" : undefined}>
                      {img.state === "up" ? "Uploading…" : "Not sent"}
                    </span>
                  )}
                  <button
                    type="button"
                    aria-label={`Remove ${img.name}`}
                    onClick={() => removeImage(img.id)}
                    className="absolute right-1 top-1 grid h-5 w-5 place-items-center rounded-full bg-black/60 text-[10px] text-white opacity-0 transition group-hover:opacity-100"
                  >
                    <CloseIcon />
                  </button>
                </div>
              ))}
            </div>
          )}

          <textarea
            ref={taRef}
            rows={1}
            value={text}
            disabled={live}
            placeholder={live ? "Cyrus is forging… you can watch the beams travel the branch." : placeholder}
            onChange={(e) => {
              setText(e.target.value);
              fx.keystroke();
              pulseTyping();
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
                e.preventDefault();
                submit();
              }
            }}
            onPaste={onPaste}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            className="prompt-textarea block max-h-[180px] w-full resize-none bg-transparent px-4 pb-2 pt-2.5 text-[15px] leading-relaxed text-cy-ink outline-none disabled:opacity-60"
            aria-label="Describe your mod"
          />

          {/* Toolbar */}
          <div className="flex items-center gap-1.5 px-2.5 pb-2.5">
            <ModelSelect disabled={live} />
            <input
              ref={fileRef}
              type="file"
              accept="image/*"
              multiple
              hidden
              onChange={(e) => {
                addFiles(Array.from(e.target.files ?? []));
                e.target.value = "";
              }}
            />
            <button
              type="button"
              onClick={() => fileRef.current?.click()}
              disabled={live}
              className="cy5-btn-ghost h-9 w-9 text-[17px] disabled:opacity-40"
              title="Attach reference images (or paste them)"
              aria-label="Attach images"
            >
              <ImageIcon />
            </button>
            {realTarget && !(selection.level === "mod" && mod?.real) && (
              <label className="relative hidden h-9 items-center rounded-xl px-2 text-[11.5px] text-cy-muted transition hover:text-cy-ink md:inline-flex" title="The Paper version your server runs">
                <span className="whitespace-nowrap font-mono">Paper {mcVersion}</span>
                <select
                  value={mcVersion}
                  onChange={(e) => setMcVersion(e.target.value)}
                  disabled={live}
                  aria-label="Paper version"
                  className="absolute inset-0 cursor-pointer opacity-0"
                >
                  {MB_VERSIONS.map((v) => (
                    <option key={v} value={v}>
                      Paper {v}
                    </option>
                  ))}
                </select>
              </label>
            )}
            <span className={`ml-1 hidden whitespace-nowrap text-[11px] text-cy-faint ${text.trim() && realTarget ? "" : "sm:inline"}`}>
              <span className="cy5-kbd">Enter</span> to forge · <span className="cy5-kbd">Shift</span>+<span className="cy5-kbd">Enter</span> newline
            </span>

            <div className="ml-auto flex items-center gap-1.5">
              {realTarget ? (
                text.trim() && (
                  <span className="hidden items-center rounded-lg px-2 py-1 text-[11px] font-medium text-cy-muted sm:inline-flex">
                    <CyrusTokenEstimate text={text} model={model.id} change={selection.level === "mod" && !!mod?.real} />
                  </span>
                )
              ) : (
                <span className="hidden items-center gap-1 rounded-lg px-2 py-1 text-[11px] font-medium text-cy-muted sm:inline-flex" title="Cyrus builds Minecraft plugins today. Other games forge a template preview and spend no tokens.">
                  Template preview
                </span>
              )}
              <VoiceButton
                disabled={live}
                onStart={() => {
                  voiceBase.current = text;
                }}
                onTranscript={(t) => {
                  const base = voiceBase.current;
                  setText(base ? `${base.trimEnd()} ${t}` : t);
                  pulseTyping();
                }}
              />
              {live ? (
                <button
                  type="button"
                  onClick={cancelForge}
                  className="grid h-9 w-9 place-items-center rounded-xl bg-[rgb(var(--glow)/0.14)] text-[15px] text-cy-ink transition hover:bg-rose-500/20 hover:text-rose-400"
                  aria-label="Stop forging"
                  title="Stop"
                >
                  <StopIcon />
                </button>
              ) : (
                <button
                  type="button"
                  onClick={submit}
                  disabled={!sendable}
                  aria-label="Forge mod"
                  title={uploading ? "Uploading images…" : "Forge"}
                  className="group relative grid h-9 w-9 place-items-center overflow-hidden rounded-xl text-[16px] text-white transition enabled:hover:scale-105 enabled:active:scale-95 disabled:opacity-35"
                  style={{
                    background: "linear-gradient(135deg, #8b5cf6, #6366f1 45%, #06b6d4)",
                    boxShadow: sendable ? "0 0 22px rgb(139 92 246 / 0.6), inset 0 1px 0 rgb(255 255 255 / 0.3)" : undefined,
                  }}
                >
                  <span className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/40 to-transparent transition duration-700 group-enabled:group-hover:translate-x-full" />
                  <SendIcon className="relative" />
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* beside the open panel there is no room for the idea row (the panel is the focus) */}
      {!live && !text && !dockStyle && <StarterIdeas onPick={pickIdea} />}
    </div>
  );
}
// Cyrus v5 <-> Nxeon: turns the account's real builds (ModBuild rows, grouped into projects by
// lib/cyrus/projects.ts) into the studio's network model (Mod + ModVersion, lib/cyrus/types.ts).
// Pure and client-safe; unit-tested in test/cyrus.test.ts.
//
// A real project lives on the Minecraft branch (the only game the build service compiles today).
// Its versions are its builds; their files load lazily from the build service
// (/api/mod-builder/builds/:id/source). Notes, favourite and the restored head stay in the DB
// (PATCH /api/mod-builder/projects/:rootId), exactly as before.
import { isTerminal, type ModBuildView } from "../modbuilder/types";
import { CATEGORIES, CATEGORY_BY_KEY } from "./data";
import { languageForPath } from "./engine/kit";
import { groupProjects, viewMeta, type CyrusProject } from "./projects";
import type { CategoryKey, Game, Mod, ModFile, ModVersion, ModelId } from "./types";

export const REAL_PREFIX = "nx-";
export const realModId = (rootId: string) => `${REAL_PREFIX}${rootId}`;
export const isRealModId = (id: string | undefined | null): id is string => !!id && id.startsWith(REAL_PREFIX);
export const rootOfRealMod = (id: string) => id.slice(REAL_PREFIX.length);

/** The category branches a real game may grow: its own plus at most this many more. */
const MAX_EXTRA_CATEGORIES = 2;
const FALLBACK: CategoryKey = "mechanics";

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const hasWord = (text: string, word: string) => new RegExp(`(^|[^a-z0-9])${escapeRe(word)}(s|es)?([^a-z0-9]|$)`).test(text);

/** Same keyword scoring the forge router uses (lib/cyrus/engine routePrompt), over the build's own words. */
export function scoreCategory(text: string): CategoryKey | null {
  const p = text.toLowerCase();
  let best: CategoryKey | null = null;
  let bestScore = 0;
  for (const c of CATEGORIES) {
    let score = 0;
    for (const k of c.keywords) if (hasWord(p, k)) score += k.length;
    if (score > bestScore) { bestScore = score; best = c.key; }
  }
  return best;
}

const projectText = (p: CyrusProject) => {
  const head = p.head ?? p.latest;
  const s = head.result?.summary;
  return [p.title, head.pluginName, s?.tagline, s?.text, p.builds[0]?.prompt].filter(Boolean).join(" \n ");
};

/**
 * Category per project, keeping the branch readable: the game's own categories, plus up to two
 * more for whatever else the account builds; anything beyond folds into Mechanics.
 */
export function categoriesFor(projects: CyrusProject[], game: Game): Map<string, CategoryKey> {
  const raw = new Map<string, CategoryKey>();
  for (const p of projects) raw.set(p.rootId, scoreCategory(projectText(p)) ?? FALLBACK);
  const own = new Set(game.categories);
  const extraCount = new Map<CategoryKey, number>();
  for (const c of raw.values()) if (!own.has(c)) extraCount.set(c, (extraCount.get(c) ?? 0) + 1);
  let extras = [...extraCount.entries()].sort((a, b) => b[1] - a[1]).map(([c]) => c);
  if (extras.length > MAX_EXTRA_CATEGORIES) {
    const keep = extras.filter((c) => c !== FALLBACK).slice(0, MAX_EXTRA_CATEGORIES - (own.has(FALLBACK) ? 0 : 1));
    extras = own.has(FALLBACK) ? keep : [FALLBACK, ...keep];
  }
  const allowed = new Set<CategoryKey>([...own, ...extras]);
  const out = new Map<string, CategoryKey>();
  for (const [id, c] of raw) out.set(id, allowed.has(c) ? c : FALLBACK);
  return out;
}

const modelOf = (b: ModBuildView): ModelId => viewMeta(b).model ?? "saka";

/** Only the files a server owner cares about (same filter the v4 studio used). */
export const visibleSource = (files: { path: string; size: number }[]) =>
  files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json");

export function versionOf(b: ModBuildView, n: number): ModVersion {
  const s = b.result?.summary;
  return {
    id: b.id,
    label: `v${n}`,
    createdAt: Date.parse(b.createdAt),
    model: modelOf(b),
    credits: 0,
    prompt: b.changeRequest || b.prompt,
    summary: s?.changes || s?.tagline || (b.status === "failed" ? b.error || "This version didn't build." : b.changeRequest || b.prompt),
    files: [],
    additions: 0,
    deletions: 0,
    real: {
      buildId: b.id,
      status: b.status,
      mcVersion: b.mcVersion,
      jarName: b.jarName,
      jarSize: b.jarSize,
      error: b.error,
      attempts: b.attempts,
      durationMs: b.durationMs,
      paths: visibleSource(b.result?.files ?? []),
    },
  };
}

/** Cyrus's notes for a real build, from what the build service reported. */
export function realNotes(b: ModBuildView | null): string {
  if (!b) return "";
  if (b.status === "failed") return `# Didn't build\n\n${b.error || "The build stopped before it finished."}\n\nTokens held for a failed build go back to you.`;
  if (!isTerminal(b.status)) return "# Building\n\nCyrus is writing, compiling and safety-checking this version right now.";
  const r = b.result;
  const s = r?.summary;
  const out: string[] = [`# ${b.pluginName || "Your plugin"}${b.version ? ` v${b.version}` : ""}`];
  if (s?.text) out.push("", s.text);
  if (s?.howToUse?.length) out.push("", "## How to use", ...s.howToUse.map((x) => `- ${x}`));
  if (r?.commands?.length) out.push("", "## Commands", ...r.commands.map((c) => `- \`${c.usage}\` ${c.description}${c.permission ? ` (\`${c.permission}\`)` : ""}`));
  if (r?.permissions?.length) out.push("", "## Permissions", ...r.permissions.map((p) => `- \`${p.node}\` ${p.description} (default: ${p.default})`));
  if (r?.config?.length) out.push("", "## Config", ...r.config.map((c) => `- \`${c.key}\` ${c.description} (default \`${c.default}\`)`));
  if (s?.limitations?.length) out.push("", "## Limits", ...s.limitations.map((x) => `- ${x}`));
  const safety = r?.safety?.verdict;
  out.push("", "## Build", `- Paper ${b.mcVersion} · built in ${Math.max(1, Math.round((b.durationMs ?? 0) / 1000))}s${b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}`);
  if (safety) out.push(`- Safety check: **${safety === "pass" ? "passed" : safety === "warn" ? "passed with notes" : "blocked"}** (no internet, no system access)`);
  return out.join("\n");
}

export type RealModel = {
  projects: CyrusProject[];
  mods: Mod[];
  versions: Record<string, ModVersion[]>;
  active: Record<string, string>;
  notes: Record<string, string>;
  aiNotes: Record<string, string>;
};

/** Every project of the account as a mod on `game`'s branch (newest activity first). */
export function deriveReal(builds: ModBuildView[], game: Game): RealModel {
  const projects = groupProjects(builds);
  const cats = categoriesFor(projects, game);
  const out: RealModel = { projects, mods: [], versions: {}, active: {}, notes: {}, aiNotes: {} };
  for (const p of projects) {
    const id = realModId(p.rootId);
    const head = p.head;
    const s = (head ?? p.latest).result?.summary;
    out.mods.push({
      id,
      gameId: game.id,
      category: cats.get(p.rootId) ?? FALLBACK,
      name: p.title,
      summary: s?.tagline || s?.text?.split(/(?<=\.)\s/)[0] || p.builds[0].prompt.slice(0, 140),
      tags: [],
      createdAt: Date.parse(p.updatedAt || p.latest.createdAt),
      versions: [],
      real: { rootId: p.rootId, running: !!p.running, failed: !head && !p.running, headBuildId: head?.id ?? null, favourite: !!p.meta.favourite },
    });
    out.versions[id] = p.builds.map((b, i) => versionOf(b, i + 1));
    out.active[id] = (head ?? p.latest).id;
    out.notes[id] = p.meta.notes ?? "";
    out.aiNotes[id] = realNotes(head ?? p.latest);
  }
  return out;
}

/** A source file as the studio's ModFile. */
export const toModFile = (path: string, content: string): ModFile => ({ path, language: languageForPath(path), content });

/** Is CATEGORY_BY_KEY aware of this key (guards stale data). */
export const knownCategory = (k: string): k is CategoryKey => k in CATEGORY_BY_KEY;

"use client";

// The forge client (handoff lib/forge.ts): streams /api/cyrus/generate into the store and drives
// the network's beams and packets. Nxeon: a Minecraft forge is a REAL build (the stream carries its
// real progress and code, tokens are held and settled by the economy); every other game is the
// handoff's template preview. No local credits.
import { cyrusTokens } from "@/components/cyrus-tokens";
import { CATEGORY_BY_KEY, MODEL_BY_ID, categoryNodeId } from "./data";
import { diffStats } from "./engine";
import { fx } from "./fx";
import { isRealModId, realModId } from "./real";
import { CORE_ID, findMod, getGame, isJobLive, useStore, versionsOf, type Job } from "./store";
import type { GenEvent, Mod, ModVersion, ModelId } from "./types";

let controller: AbortController | null = null;

const patchJob = (fn: (job: Job) => Partial<Job>) =>
  useStore.setState((s) => (s.job ? { job: { ...s.job, ...fn(s.job) } } : {}));

export function cancelForge() {
  const job = useStore.getState().job;
  // A real build is stopped on the builder too (its held tokens are settled by the economy).
  if (job?.buildId && isJobLive(job)) void fetch(`/api/mod-builder/builds/${job.buildId}/cancel`, { method: "POST" }).catch(() => {});
  controller?.abort();
}

export type ForgeImage = { url: string; uploadId?: string };

type Ctx = { createdModId: string | null; path: string[]; rgb: string; finished: boolean; startedAt: number };

function makeHandler(ctx: Ctx) {
  // Chunks arrive faster than React needs to paint; batch them per animation frame.
  const pending = new Map<string, string>();
  let raf = 0;
  const flush = () => {
    raf = 0;
    if (!pending.size) return;
    const batch = new Map(pending);
    pending.clear();
    patchJob((job) => ({ files: job.files.map((f) => (batch.has(f.path) ? { ...f, content: f.content + batch.get(f.path) } : f)) }));
  };
  const stop = () => cancelAnimationFrame(raf);

  const handle = (ev: GenEvent) => {
    switch (ev.type) {
      case "start":
        patchJob(() => ({ id: ev.jobId, status: "thinking", credits: ev.credits, real: !!ev.real, ...(ev.real ? { buildId: ev.jobId } : {}) }));
        break;

      case "build":
        useStore.getState().upsertReal([ev.build]);
        patchJob(() => ({ buildId: ev.build.id, real: true }));
        break;

      case "ping":
        break;

      case "think":
        patchJob((job) => ({
          steps: [
            ...job.steps.filter((s) => s.id !== ev.id),
            { id: ev.id, label: ev.label, detail: ev.detail, done: false, startedAt: job.steps.find((s) => s.id === ev.id)?.startedAt ?? Date.now() },
          ],
        }));
        fx.ripple();
        if (ctx.path.length) fx.packets(ctx.path.slice(0, 3), 1, { rgb: ctx.rgb, speed: 1.4 });
        break;

      case "think-done":
        patchJob((job) => ({ steps: job.steps.map((s) => (s.id === ev.id ? { ...s, done: true, endedAt: Date.now() } : s)) }));
        break;

      case "route": {
        const game = getGame(ev.gameId);
        ctx.rgb = game?.rgb ?? ctx.rgb;
        ctx.path = [CORE_ID, ev.gameId, categoryNodeId(ev.gameId, ev.category), ev.modId];
        patchJob(() => ({ gameId: ev.gameId, category: ev.category, modId: ev.modId, modName: ev.modName }));
        if (!findMod(ev.modId) && !isRealModId(ev.modId)) {
          const mod: Mod = { id: ev.modId, gameId: ev.gameId, category: ev.category, name: ev.modName, summary: ev.summary, tags: ev.tags, createdAt: Date.now(), versions: [] };
          ctx.createdModId = ev.modId;
          useStore.setState((s) => ({ userMods: [...s.userMods, mod] }));
        }
        useStore.getState().select({ level: "mod", gameId: ev.gameId, category: ev.category, modId: ev.modId }, { openPanel: true, focus: "path" });
        useStore.setState({ panelTab: "code" });
        fx.setMode("forging");
        fx.startStream(ctx.path, ctx.rgb);
        fx.packets(ctx.path, 4, { rgb: ctx.rgb, speed: 1.2, size: 1.4 });
        break;
      }

      case "file":
        patchJob((job) => ({
          status: "writing",
          activeFile: ev.path,
          files: job.files.some((f) => f.path === ev.path) ? job.files : [...job.files, { path: ev.path, language: ev.language, content: "" }],
        }));
        useStore.setState({ activeFile: ev.path });
        break;

      case "chunk":
        pending.set(ev.path, (pending.get(ev.path) ?? "") + ev.text);
        if (!raf) raf = requestAnimationFrame(flush);
        break;

      case "file-set":
        // the builder rewrote or edited a file in place: replace it (after any queued chunks)
        stop();
        flush();
        patchJob((job) => ({ files: job.files.map((f) => (f.path === ev.path ? { ...f, content: ev.content } : f)), activeFile: ev.path }));
        fx.packets(ctx.path, 1, { rgb: ctx.rgb, speed: 1.6 });
        break;

      case "file-done":
        fx.packets(ctx.path, 2, { rgb: ctx.rgb, speed: 1.6 });
        break;

      case "done": {
        stop();
        flush();
        ctx.finished = true;
        const s = useStore.getState();
        const job = s.job!;
        const seconds = ((performance.now() - ctx.startedAt) / 1000).toFixed(1);
        if (job.real && job.buildId) {
          // The version IS the real build: keep the streamed code as its files and re-read the
          // account (build list, token balance).
          s.seedRealFiles(job.buildId, job.files);
          // the final `build` event already refreshed the project: it carries the plugin's real name now
          const mod = findMod(job.modId);
          useStore.setState((st) => ({ job: st.job ? { ...st.job, status: "done", finishedAt: Date.now(), modName: mod?.name ?? st.job.modName } : null }));
          void s.refreshReal();
          void cyrusTokens.refresh();
          const n = mod ? versionsOf(mod, s.userVersions).findIndex((v) => v.id === job.buildId) + 1 : 0;
          finishFx(job.modId ?? "", ctx);
          s.toast({
            tone: "success",
            title: `${mod?.name ?? job.modName ?? "Your plugin"}${n ? ` v${n}` : ""} is ready`,
            body: `${job.files.length} files · ${ev.tokens !== undefined ? `${ev.tokens.toLocaleString("en-US")} tokens · ` : ""}${seconds}s · compiled and safety-checked`,
            rgb: ctx.rgb,
          });
          break;
        }
        const mod = findMod(job.modId);
        if (!mod) break;
        const prev = versionsOf(mod, s.userVersions);
        const prevActive = prev.find((v) => v.id === s.activeVersion[mod.id]) ?? prev[prev.length - 1];
        const n = prev.length + 1;
        const { additions, deletions } = diffStats(prevActive?.files, job.files);
        const version: ModVersion = {
          id: `${mod.id}@v${n}-${Date.now().toString(36)}`,
          label: `v${n}`,
          createdAt: Date.now(),
          model: job.model,
          credits: 0,
          prompt: job.prompt,
          summary: ev.summary,
          files: job.files,
          additions,
          deletions,
        };
        useStore.setState((st) => ({
          userVersions: { ...st.userVersions, [mod.id]: [...(st.userVersions[mod.id] ?? []), version] },
          activeVersion: { ...st.activeVersion, [mod.id]: version.id },
          aiNotes: { ...st.aiNotes, [mod.id]: ev.notes },
          job: st.job ? { ...st.job, status: "done", finishedAt: Date.now() } : null,
        }));
        finishFx(mod.id, ctx);
        s.toast({ tone: "success", title: `${mod.name} ${version.label} forged`, body: `${job.files.length} files · template preview, no tokens · ${seconds}s`, rgb: ctx.rgb });
        break;
      }

      case "error":
        throw new Error(ev.message);
    }
  };
  return { handle, stop };
}

function finishFx(modId: string, ctx: Ctx) {
  fx.stopStream();
  fx.setMode("idle");
  fx.burst(modId, ctx.rgb);
  fx.packets([...ctx.path].reverse(), 5, { rgb: "196 181 253", speed: 1.3, gap: 0.12 });
  window.setTimeout(() => fx.ripple(true), 900);
}

async function readStream(res: Response, handle: (ev: GenEvent) => void) {
  const reader = res.body!.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    let nl: number;
    while ((nl = buffer.indexOf("\n")) >= 0) {
      const line = buffer.slice(0, nl).trim();
      buffer = buffer.slice(nl + 1);
      if (line) handle(JSON.parse(line) as GenEvent);
    }
  }
}

class HttpError extends Error {
  constructor(message: string, readonly json: Record<string, unknown>) {
    super(message);
  }
}

/** Run one forge request, and keep following a real build if the connection drops. */
async function run(open: (signal: AbortSignal) => Promise<Response>, ctx: Ctx) {
  const { handle, stop } = makeHandler(ctx);
  controller = new AbortController();
  const signal = controller.signal;
  try {
    let res = await open(signal);
    for (let attempt = 0; ; attempt++) {
      if (!res.ok || !res.body) {
        const j = (await res.json().catch(() => ({ error: res.statusText }))) as Record<string, unknown>;
        throw new HttpError(String(j.error ?? "The forge did not respond"), j);
      }
      await readStream(res, handle);
      if (ctx.finished) break;
      // A real build outlives the connection: re-attach (the server re-sends the code so far).
      const job = useStore.getState().job;
      if (!job?.buildId || attempt >= 4 || signal.aborted) throw new Error("The stream ended before the mod was packaged");
      await new Promise((r) => setTimeout(r, 1200 * (attempt + 1)));
      patchJob(() => ({ files: [], steps: [] }));
      res = await fetch(`/api/cyrus/generate?follow=${encodeURIComponent(job.buildId)}`, { signal });
    }
  } catch (err) {
    stop();
    const aborted = signal.aborted;
    const s = useStore.getState();
    const real = !!s.job?.real || !!s.job?.buildId;
    fx.stopStream();
    fx.setMode("idle");
    if (err instanceof HttpError) cyrusTokens.handleBuildError(err.json);
    useStore.setState((st) => ({
      // A brand-new template mod that never finished packaging shouldn't linger as an empty node.
      userMods: ctx.createdModId ? st.userMods.filter((m) => m.id !== ctx.createdModId) : st.userMods,
      job: st.job ? { ...st.job, status: aborted ? "cancelled" : "error", error: aborted ? undefined : String((err as Error).message), finishedAt: Date.now() } : null,
    }));
    if (ctx.createdModId) useStore.getState().select({ level: "category", gameId: s.job?.gameId, category: s.job?.category }, { openPanel: false });
    if (real) {
      void s.refreshReal();
      void cyrusTokens.refresh();
    }
    s.toast(
      aborted
        ? { tone: "info", title: real ? "Build stopped" : "Forge stopped", body: real ? "Cyrus stopped the build. Tokens it didn't use go back to you." : "Nothing was saved." }
        : { tone: "error", title: real ? "Didn't build" : "Forge failed", body: (err as Error).message },
    );
  } finally {
    controller = null;
  }
}

export async function forge(prompt: string, images: ForgeImage[] = []) {
  const state = useStore.getState();
  if (isJobLive(state.job)) return;
  const text = prompt.trim();
  if (!text) return;
  const model = MODEL_BY_ID[state.model];

  const sel = state.selection;
  const picked = sel.level === "mod" ? findMod(sel.modId) : undefined;
  // An idea pill is a prompt, not a mod: a forge from it is a brand-new mod in its category.
  const refineMod = picked?.idea ? undefined : picked;
  if (refineMod?.real && !refineMod.real.headBuildId) {
    state.toast({
      tone: "error",
      title: "Nothing to change yet",
      body: refineMod.real.running ? "Cyrus is still building this mod. Ask for the next change when it's ready." : "This mod has no version that built. Describe it again to forge a new one.",
    });
    return;
  }
  const prior = refineMod ? versionsOf(refineMod, state.userVersions) : [];
  const context = refineMod
    ? { gameId: refineMod.gameId, category: refineMod.category, modId: refineMod.id, modName: refineMod.name, version: prior.length + 1 }
    : { gameId: sel.gameId, category: sel.category };

  const ctx: Ctx = { createdModId: null, path: [], rgb: "167 139 250", finished: false, startedAt: performance.now() };
  useStore.setState({
    job: {
      id: "pending",
      status: "connecting",
      prompt: text,
      model: model.id,
      images: images.map((i) => i.url),
      credits: 0,
      refining: !!refineMod,
      version: refineMod ? prior.length + 1 : 1,
      steps: [],
      files: [],
      startedAt: Date.now(),
    },
  });
  fx.setMode("thinking");
  fx.ripple(true);

  await run(
    (signal) =>
      fetch("/api/cyrus/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: text,
          model: model.id,
          images: images.length,
          attachmentIds: images.map((i) => i.uploadId).filter(Boolean),
          mcVersion: state.mcVersion,
          context,
          games: state.customGames,
        }),
        signal,
      }),
    ctx,
  );
}

/** Re-attach to a real build that is still running (page load, a build started elsewhere). */
export async function followForge(buildId: string) {
  const state = useStore.getState();
  if (isJobLive(state.job)) return;
  const b = state.realBuilds.find((x) => x.id === buildId);
  if (!b) return;
  const mod = findMod(realModId(b.rootBuildId ?? b.id));
  const n = mod ? versionsOf(mod, state.userVersions).findIndex((v) => v.id === buildId) + 1 : 1;
  useStore.setState({
    job: {
      id: buildId,
      status: "connecting",
      prompt: b.changeRequest || b.prompt,
      model: ((b.cyrus as { model?: ModelId } | null)?.model ?? "saka") as ModelId,
      images: [],
      credits: 0,
      refining: !!b.baseBuildId,
      version: Math.max(1, n),
      steps: [],
      files: [],
      startedAt: Date.parse(b.createdAt) || Date.now(),
      buildId,
      real: true,
    },
  });
  fx.setMode("thinking");
  const ctx: Ctx = { createdModId: null, path: [], rgb: "167 139 250", finished: false, startedAt: performance.now() };
  await run((signal) => fetch(`/api/cyrus/generate?follow=${encodeURIComponent(buildId)}`, { signal }), ctx);
