// Cyrus: group a user's builds into projects (pure, client-safe, unit-tested).
// A project = one root build plus every change built on it (rootBuildId).
import { isTerminal, type ModBuildView } from "../modbuilder/types";
import { readCyrusMeta, type CyrusMeta } from "./meta";

export type CyrusProject = {
  rootId: string;
  /** Oldest first. */
  builds: ModBuildView[];
  latest: ModBuildView;
  /** The current version: the restored head if set, else the newest succeeded build. */
  head: ModBuildView | null;
  running: ModBuildView | null;
  meta: CyrusMeta;
  title: string;
  updatedAt: string;
};

export const viewMeta = (b: ModBuildView): CyrusMeta => readCyrusMeta(b.cyrus);

export function projectTitle(meta: CyrusMeta, head: ModBuildView | null, latest: ModBuildView): string {
  if (meta.title) return meta.title;
  const name = head?.pluginName || latest.pluginName;
  if (name) return spaced(name);
  return draftTitle(latest.prompt);
}

/** "DailyRewards" -> "Daily Rewards" (plugin names are PascalCase identifiers). */
export function spaced(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/_/g, " ").trim();
}

/** A short working title from the prompt, for builds that have no plugin name yet. */
export function draftTitle(prompt: string): string {
  let p = prompt.replace(/\s+/g, " ").trim();
  for (let i = 0; i < 3; i++) p = p.replace(/^(a|an|the|make|build|create|i want|please|me)\s+/i, "").replace(/^\/(?=\w)/, "");
  const cut = p.split(/[.:;!?]| - |, (?=[a-z])/)[0] || p;
  const words = cut.split(" ").slice(0, 5).join(" ");
  const t = words.length > 34 ? words.slice(0, 33).trimEnd() + "…" : words;
  return t ? t[0].toUpperCase() + t.slice(1) : "Untitled mod";
}

export function groupProjects(builds: ModBuildView[]): CyrusProject[] {
  const byRoot = new Map<string, ModBuildView[]>();
  for (const b of builds) {
    const r = b.rootBuildId || b.id;
    if (!byRoot.has(r)) byRoot.set(r, []);
    byRoot.get(r)!.push(b);
  }
  const out: CyrusProject[] = [];
  for (const [rootId, list] of byRoot) {
    list.sort((x, y) => x.createdAt.localeCompare(y.createdAt));
    const root = list.find((b) => b.id === rootId) ?? list[0];
    const meta = viewMeta(root);
    const latest = list[list.length - 1];
    const succeeded = list.filter((b) => b.status === "succeeded");
    const head = (meta.headBuildId && succeeded.find((b) => b.id === meta.headBuildId)) || succeeded[succeeded.length - 1] || null;
    const running = [...list].reverse().find((b) => !isTerminal(b.status)) ?? null;
    const updatedAt = list.reduce((m, b) => (b.finishedAt && b.finishedAt > m ? b.finishedAt : b.createdAt > m ? b.createdAt : m), "");
    out.push({ rootId, builds: list, latest, head, running, meta, title: projectTitle(meta, head, latest), updatedAt });
  }
  // Running first, then favourites, then most recent activity.
  out.sort((a, b) => (+!!b.running - +!!a.running) || (+!!b.meta.favourite - +!!a.meta.favourite) || b.updatedAt.localeCompare(a.updatedAt));
  return out;
}

/** 1-based version number of a build inside its project (every build counts, failed ones too). */
export function versionNumber(p: CyrusProject, buildId: string): number {
  return p.builds.findIndex((b) => b.id === buildId) + 1;
}

/** The project a build belongs to. */
export function projectOf(projects: CyrusProject[], buildId: string | null): CyrusProject | null {
  if (!buildId) return null;
  return projects.find((p) => p.builds.some((b) => b.id === buildId)) ?? null;
}

/** Stable small hash for per-project glyphs. */
export function hashSeed(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
