/** Provider categories that mean "adds things to the world" (Modrinth / Thunderstore / mod.io wording). */
const CONTENT_CATS = new Set([
  "adventure", "equipment", "technology", "mobs", "decoration", "magic", "worldgen", "food", "storage",
  "transportation", "kitchen-sink", "content", "building", "item", "items", "world", "npc", "overhaul",
  "creatures", "weapons", "armor", "biomes", "structures", "dimensions",
]);
/** Categories that clearly don't (server-side behaviour, performance, libraries). */
const SAFE_CATS = new Set([
  "optimization", "library", "libraries", "utility", "management", "social", "lightweight", "admin", "admin_tools",
  "quality of life", "qol", "tweaks", "visual", "language", "performance", "chat", "dev_tools", "core",
]);

/**
 * Could disabling this specific mod delete things from the world? Errs toward
 * YES: a mod we can't classify on a content-capable game is treated as content.
 */
export function contentRisk(family: string, variant: string | null, mod: ToggleModFacts): { risk: boolean; why: string } {
  const pol = familyTogglePolicy(family, variant);
  if (pol.safety !== "SAFE_WITH_WARNING") return { risk: false, why: "plugins on this game don't add world content" };
  const cats = new Set([...lc([mod.category]), ...lc(mod.categories), ...lc(mod.tags)]);
  const hit = [...cats].find((c) => CONTENT_CATS.has(c));
  if (hit) return { risk: true, why: `listed as "${hit}"` };
  if (family === "factorio") return { risk: true, why: "Factorio mods usually define prototypes the save stores" };
  if (family === "minecraft" && (cats.has("datapacks") || lc(mod.loaders).includes("datapack"))) {
    return { risk: true, why: "datapacks can add world generation, structures and dimensions" };
  }
  const known = [...cats].filter((c) => !["mods", "plugins", "misc", "other", "fun", "game-mechanics", "gameplay", "mechanics"].includes(c));
  if (known.length && known.every((c) => SAFE_CATS.has(c))) return { risk: false, why: `listed only as ${known.join(", ")}` };
  return { risk: true, why: "we can't tell from its listing whether it adds content" };
}

/** Modpacks are a bundle of other packages + config overrides: "disable" isn't meaningful. */
export function isModpack(mod: ToggleModFacts): boolean {
  const cats = new Set([...lc([mod.category]), ...lc(mod.categories)]);
  return cats.has("modpacks") || cats.has("modpack") || lc(mod.loaders).includes("mrpack");
}

