export const PER_PAGE = 24;

/**
 * The browse query. `family` is the per-game page's fixed family (the hub
 * passes `p.game` instead). The category path uses the taxonomy's in-memory
 * index when that alone can answer (fast), and otherwise narrows
 * queryCatalogMods to the category's member ids so loader/version/raw-category
 * filters and every sort still apply in the database.
 */
export async function runLabsQuery(p: LabsParams, family?: string): Promise<CatalogPage> {
  const fam = family ?? p.game;
  if (p.cat) {
    const simple = !p.loader && !p.version && !p.category && (p.sort === "featured" || p.sort === "downloads" || p.sort === "latest");
