/**
 * Category + (loader | version | raw category | updated/rating sort): the
 * category's member ids (from the taxonomy index) go to Postgres as ONE array
 * parameter (`= ANY($1)`), never as an IN-list — a big category is 20k+ ids,
 * which as bind parameters would hit Postgres' 32,767 limit and make Prisma
 * split the query (breaking ORDER BY/OFFSET). Same public rule
 * (active && upstreamOk) and search fields as queryCatalogMods; rows are then
 * hydrated by the taxonomy's cardsByIds (the shared card shape).
 */
async function categoryPage(ids: string[], p: LabsParams, family?: string): Promise<CatalogPage> {
  if (!ids.length) return { mods: [], total: 0, page: 1, totalPages: 1, perPage: PER_PAGE };
  const like = p.q ? `%${p.q.replace(/[\\%_]/g, (c) => `\\${c}`)}%` : null;
  const where = Prisma.sql`"active" = true AND "upstreamOk" = true AND "id" = ANY(${ids}::text[])
    ${family ? Prisma.sql`AND "gameFamily" = ${family}` : Prisma.empty}
    ${p.loader ? Prisma.sql`AND ${p.loader} = ANY("loaders")` : Prisma.empty}
    ${p.version ? Prisma.sql`AND ${p.version} = ANY("gameVersions")` : Prisma.empty}
    ${p.category ? Prisma.sql`AND "category" = ${p.category}` : Prisma.empty}
    ${like ? Prisma.sql`AND ("name" ILIKE ${like} OR "category" ILIKE ${like} OR "description" ILIKE ${like})` : Prisma.empty}`;
  const order: Record<LabsSort, Prisma.Sql> = {
    featured: Prisma.sql`"featured" DESC, "downloads" DESC NULLS LAST, "popularity" DESC, "name" ASC`,
    downloads: Prisma.sql`"downloads" DESC NULLS LAST, "name" ASC`,
    rating: Prisma.sql`"downloads" DESC NULLS LAST, "name" ASC`,
    latest: Prisma.sql`"createdAt" DESC`,
    updated: Prisma.sql`"upstreamUpdatedAt" DESC NULLS LAST, "name" ASC`,
  };
  const [{ n }] = await db.$queryRaw<{ n: bigint }[]>(Prisma.sql`SELECT count(*) AS n FROM "GameMod" WHERE ${where}`);
  const total = Number(n);
  const totalPages = Math.max(1, Math.ceil(total / PER_PAGE));
  const page = Math.min(p.page, totalPages);
  const rows = await db.$queryRaw<{ id: string }[]>(Prisma.sql`
    SELECT "id" FROM "GameMod" WHERE ${where} ORDER BY ${order[p.sort]} LIMIT ${PER_PAGE} OFFSET ${(page - 1) * PER_PAGE}`);
  const mods = await cardsByIds(rows.map((r) => r.id));
  if (p.sort === "rating") mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
  return { mods, total, page, totalPages, perPage: PER_PAGE };
}

