export const DEFAULT_EFFECTS: Record<CategoryKey, EffectKey[]> = {
  weapons: ["storm", "fire", "frost"],
  creatures: ["void", "poison", "summon"],
  worlds: ["lunar", "frost"],
  mechanics: ["auto", "neon"],
  shaders: ["lunar", "neon"],
  magic: ["storm", "lunar", "frost"],
  quests: ["lunar", "void"],
  interface: ["neon", "auto"],
  audio: ["lunar", "neon"],
  vehicles: ["flight", "neon"],
  items: ["auto", "heal"],
  characters: ["heal", "lunar"],
};

export function effectsFor(input: TemplateInput): Effect[] {
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const hits = EFFECTS.filter((e) => e.re.test(text)).slice(0, 2);
  if (hits.length) return hits;
  const pool = DEFAULT_EFFECTS[input.category.key];
  const key = pool[hashStr(input.modName) % pool.length];
  return [EFFECTS.find((e) => e.key === key)!];
}

export const sub = (s: string, target: string, source: string, extra: Record<string, string> = {}) => {
  let out = s.replaceAll("TARGET", target).replaceAll("SOURCE_SRC", extra.SOURCE_SRC ?? "source").replaceAll("SOURCE", source);
  for (const [k, v] of Object.entries(extra)) out = out.replaceAll(k, v);
  return out;
};

export type Arch = "item" | "entity" | "world" | "system" | "visual";
export const ARCH: Record<CategoryKey, Arch> = {
  weapons: "item",
  items: "item",
  magic: "item",
  creatures: "entity",
  characters: "entity",
  vehicles: "entity",
  worlds: "world",
  mechanics: "system",
  quests: "system",
  interface: "system",
  audio: "system",
  shaders: "visual",
};

export const MODEL_NAME: Record<ModelId, string> = { katara: "Katara", saka: "Saka", yakko: "Yakko" };

export function deriveFeatures(input: TemplateInput): string[] {
  const n = numbers(input);
  const fx = effectsFor(input).map((e) => e.label);
  const cat = input.category.key;
  const byCat: Record<CategoryKey, string> = {
    weapons: `${n.power} bonus damage with a ${n.cooldown}s active ability`,
    items: `Right-click ability on a ${n.cooldown}s cooldown`,
    magic: `Spell radius of ${n.radius} blocks, ${n.cooldown}s recast`,
    creatures: `${n.health} HP with a second phase below 40%`,
    characters: "Daily schedule, gift tastes and heart events",
    vehicles: `Top speed tuned to ${Math.round(n.speed * 400)} km/h with drift boost`,
    worlds: `Generates every ~${n.interval * 100} blocks with custom loot`,
    mechanics: `Runs every ${n.interval}s without touching vanilla saves`,
    quests: "Multi-stage objectives with journal entries",
    interface: "Toggleable overlay with scale + opacity settings",
    audio: "Adaptive layers that crossfade with game state",
    shaders: `Color grade at ${Math.round(n.intensity * 100)}% intensity with bloom`,
  };
  const out = [...fx, byCat[cat]];
  if (input.model !== "katara") out.push("Every number exposed in config");
  if (input.model === "yakko") out.push("Covered by unit tests");
  return out.slice(0, 5);
}

