// Cyrus: one reference image pasted / dropped into the prompt (multipart field "file").
// Returns an upload id the create call can attach. The create route forwards the bytes to
// the build service (0.4+), which puts them in front of the AI (lib/cyrus/uploads.ts).
export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const rl = checkRateLimit(`mb:upload:${user.id}`, { max: 30, windowMs: 10 * 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many images. Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  const len = Number(req.headers.get("content-length") || 0);
  if (len > CYRUS_MAX_IMAGE_BYTES + 64 * 1024) return NextResponse.json({ error: "Images can be up to 5 MB." }, { status: 413 });
  const form = await req.formData().catch(() => null);
  const file = form?.get("file");
  if (!file || typeof file === "string") return NextResponse.json({ error: "No image." }, { status: 400 });
  const bytes = new Uint8Array(await file.arrayBuffer());
  const r = await saveUpload(user.id, file.name, bytes);
  if (!r.ok) return NextResponse.json({ error: r.error }, { status: 400 });
  return NextResponse.json({ upload: { id: r.id, name: r.name, type: r.type, size: r.size } }, { status: 201 });
}
