export const CYRUS_CATEGORY: Record<CyrusCategoryId, CyrusCategory> = Object.fromEntries(CYRUS_CATEGORIES.map((c) => [c.id, c])) as Record<CyrusCategoryId, CyrusCategory>;

export const isCyrusCategoryId = (v: unknown): v is CyrusCategoryId => typeof v === "string" && Object.prototype.hasOwnProperty.call(CYRUS_CATEGORY, v);

/**
 * Older ids that may still be stored somewhere -> the universal id.
 * v5 map keys (lib/cyrus/types.ts CategoryKey), v4 web categories, and words a GameSupport file
 * might reasonably use.
 */
const LEGACY: Record<string, CyrusCategoryId> = {
  // v5 archetype keys
  worlds: "environment", characters: "creatures", mechanics: "gameplay", shaders: "visuals",
  // v4 web categories (lib/cyrus/categories.ts before v6)
  worldgen: "environment", biomes: "environment", structures: "environment", other: "gameplay",
  // plain words
  world: "environment", worldgeneration: "environment", npcs: "creatures", npc: "creatures", mobs: "creatures",
  weapon: "weapons", item: "items", gear: "items", vehicle: "vehicles", mounts: "vehicles",
  mechanic: "gameplay", quest: "quests", progression: "quests", minigame: "minigames", modes: "minigames", gamemodes: "minigames",
  shop: "economy", shops: "economy", moderation: "admin", protection: "admin", qol: "utility", commands: "utility",
  ui: "interface", hud: "interface", cosmetics: "visuals", sound: "audio", optimization: "performance", optimisation: "performance",
};

const squash = (s: string) => s.trim().toLowerCase().replace(/[\s_&-]+/g, "").replace(/and/g, "");

/** Any stored / legacy / free-text category -> a universal id (unknown -> null). */
export function normalizeCategory(v: unknown): CyrusCategoryId | null {
  if (typeof v !== "string" || !v.trim()) return null;
  const raw = v.trim().toLowerCase();
  if (isCyrusCategoryId(raw)) return raw;
  const k = raw.replace(/[\s_&-]+/g, "");
  if (isCyrusCategoryId(k)) return k;
  if (Object.prototype.hasOwnProperty.call(LEGACY, k)) return LEGACY[k];
  const byLabel = CYRUS_CATEGORIES.find((c) => squash(c.label) === squash(raw));
  return byLabel?.id ?? null;
}

/** Like normalizeCategory, but always answers (unknown -> Gameplay). */
export const toCategory = (v: unknown): CyrusCategoryId => normalizeCategory(v) ?? "gameplay";

export const cyrusCategory = (id: unknown): CyrusCategory => CYRUS_CATEGORY[toCategory(id)];

/* ───────────── Per-game availability ───────────── */

const ALL = CYRUS_CATEGORY_IDS as readonly CyrusCategoryId[];
const except = (...no: CyrusCategoryId[]) => ALL.filter((c) => !no.includes(c));

/**
 * What each game's engine can express, until the game's own GameSupport file (lib/cyrus/games/<id>.ts)
 * says otherwise. Deliberately generous: an unlisted category only hides a branch, it never blocks
 * a prompt (the router falls back to the nearest available one and says so).
 */
export const DEFAULT_GAME_CATEGORIES: Record<string, CyrusCategoryId[]> = {
  // Paper plugins (server-side Java): no client shaders, but particles, sounds, menus, world gen all work.
  minecraft: [...ALL],
  // UE4SS Lua on the dedicated server.
  palworld: except("vehicles", "audio", "visuals", "minigames"),
  // Oxide / Carbon C# server plugins: CUI interfaces, no client shaders or magic systems.
  rust: except("magic", "visuals", "audio"),
  // BepInEx + Harmony, usually installed on server AND clients.
  valheim: except("minigames"),
  // Build 41/42 Lua.
  zomboid: except("magic", "minigames"),
  // tModLoader C# content mods.
  terraria: except("admin"),
};

/**
 * A game's categories: its GameSupport list when it has one (normalised; unknown ids dropped),
 * else the default table, else everything (user-added games).
 */
export function categoriesForGame(gameId: string, support?: { categories?: readonly string[] } | null): CyrusCategoryId[] {
  const fromSupport = (support?.categories ?? []).map(normalizeCategory).filter((c): c is CyrusCategoryId => !!c);
  if (fromSupport.length) return ALL.filter((c) => fromSupport.includes(c));
  return DEFAULT_GAME_CATEGORIES[gameId] ?? [...ALL];
}

/** The closest category a game supports (same store bucket first, then same engine archetype, then Gameplay). */
export function nearestAvailable(id: CyrusCategoryId, allowed: readonly CyrusCategoryId[]): CyrusCategoryId {
  if (!allowed.length || allowed.includes(id)) return id;
  const me = CYRUS_CATEGORY[id];
  return (
    allowed.find((c) => CYRUS_CATEGORY[c].store === me.store) ??
    allowed.find((c) => CYRUS_CATEGORY[c].engine === me.engine) ??
    (allowed.includes("gameplay") ? "gameplay" : allowed[0])
  );
}

/* ───────────── Engine archetype ───────────── */

const NPC_WORDS = /\b(npc|trader|merchant|companion|follower|villager|survivor|doctor|bard|keeper|shopkeeper|guard|bodyguard)s?\b/i;

/** The template-generator archetype for a universal category (the text refines the merged ones). */
export function engineCategory(id: CyrusCategoryId | string, text = ""): CategoryKey {
  const c = cyrusCategory(id);
  if (c.id === "creatures" && NPC_WORDS.test(text)) return "characters";
  return c.engine;
}

/* ───────────── Keyword scoring (shared by the router and the auto-sorter) ───────────── */

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const RE_CACHE = new Map<string, RegExp>();
function wordRe(word: string): RegExp {
  let re = RE_CACHE.get(word);
  if (!re) {
    // whole words; simple plurals; multi-word phrases tolerate any run of spaces/hyphens
    const body = word.split(/[\s-]+/).map(escapeRe).join("[\\s-]*");
    re = new RegExp(`(?:^|[^a-z0-9])${body}(?:s|es)?(?=[^a-z0-9]|$)`, "gi");
    RE_CACHE.set(word, re);
  }
  re.lastIndex = 0;
  return re;
}

export const countWord = (text: string, word: string) => (text.match(wordRe(word)) ?? []).length;

const kwWeight = (k: string) => (k.length >= 8 ? 3 : k.length >= 5 ? 2 : 1.4) * (k.includes(" ") ? 1.4 : 1);

/** Score every category over `text` (longer, more specific keywords weigh more). */
export function keywordScores(text: string): Record<CyrusCategoryId, number> {
  const p = text.toLowerCase();
  const out = Object.fromEntries(ALL.map((c) => [c, 0])) as Record<CyrusCategoryId, number>;
  if (!p.trim()) return out;
  for (const c of CYRUS_CATEGORIES) {
    for (const k of c.keywords) {
      const n = countWord(p, k);
      if (n) out[c.id] += Math.min(n, 3) * kwWeight(k);
    }
  }
  return out;
}

/** The single best category for a short text, or null when nothing matches. */
export function bestCategory(text: string, allowed?: readonly CyrusCategoryId[]): { id: CyrusCategoryId; score: number; runnerUp: number } | null {
  const s = keywordScores(text);
  const pool = allowed && allowed.length ? ALL.filter((c) => allowed.includes(c)) : ALL;
  const ranked = [...pool].sort((a, b) => s[b] - s[a] || ALL.indexOf(a) - ALL.indexOf(b));
  if (!ranked.length || s[ranked[0]] <= 0) {
    // the evidence may all sit in a category this game doesn't have: move it to the nearest one
    const top = [...ALL].sort((a, b) => s[b] - s[a])[0];
    if (allowed && allowed.length && s[top] > 0) return { id: nearestAvailable(top, allowed), score: s[top] * 0.8, runnerUp: 0 };
    return null;
  }
  return { id: ranked[0], score: s[ranked[0]], runnerUp: s[ranked[1]] ?? 0 };
}

/* ───────────── Auto-sorter ───────────── */

/**
 * API-level signals in generated code, per category. A regex hit in the source counts strongly:
 * the code is what the mod really does, whatever the prompt said. Covers the loaders Cyrus writes
 * for (Paper/Bukkit Java, Oxide C#, BepInEx/Harmony C#, tModLoader C#, Zomboid Lua, UE4SS Lua).
 */
const CODE_SIGNALS: Record<CyrusCategoryId, RegExp[]> = {
  environment: [/\bChunkGenerator\b/, /\bBlockPopulator\b/, /\bBiomeProvider\b/, /\bWorldCreator\b/, /\bStructure(Manager|Placer)\b/, /\bModBiome\b/, /\bPostWorldGen\b/, /\bZoneSystem\b/, /\bWeatherChangeEvent\b/, /\bsetStorm\b/, /\bOnWorldPrefabSpawned\b/],
  creatures: [/\bCreatureSpawnEvent\b/, /\bEntityDeathEvent\b/, /\bspawnEntity\b/, /\bLivingEntity\b/, /\bTameable\b/, /\bModNPC\b/, /\bHumanoid\b/, /\bMonsterAI\b/, /\bBaseAnimalNPC\b|\bScientistNPC\b/, /\bIsoZombie\b|\bOnZombieUpdate\b|\bOnZombieDead\b/, /\bOnEntitySpawned\b/],
  weapons: [/\bEntityDamageByEntityEvent\b/, /Material\.\w*_(SWORD|AXE)\b/, /\bMaterial\.(BOW|CROSSBOW|TRIDENT)\b/, /\bItem\.damage\b/, /\bDamageClass\.(Melee|Ranged|Magic)\b/, /\bOnPlayerAttack\b/, /\bBaseProjectile\b/, /\bOnWeaponFired\b/, /\bHitData\b/, /\bHandWeapon\b/],
  items: [/\bShapedRecipe\b|\bShapelessRecipe\b/, /\bModItem\b/, /\bItemDrop\b/, /\bObjectDB\b/, /\bOnItemCraft\b|\bOnLootSpawn\b/, /\bInventoryItemFactory\b|\bOnFillContainer\b/, /\bsetItemMeta\b/],
  magic: [/\baddEnchant\b|\bEnchantment\.\w+/, /\bPotionEffect(Type)?\b/, /\bModBuff\b/, /\bSE_Stats\b/, /\bmana\b/i, /\bspell\b/i],
  vehicles: [/\bVehicle(EnterEvent|ExitEvent|MoveEvent)\b/, /\bMinecart\b/, /\bModMount\b|\bMountData\b/, /\bBaseVehicle\b|\bMiniCopter\b|\bModularCar\b|\bOnEngineStart\b/, /\bOnEnterVehicle\b/],
  gameplay: [/\bPlayerDeathEvent\b/, /\bFoodLevelChangeEvent\b/, /\bOnPlayerRespawned?\b/, /\bOnDispenserGather\b|\bOnCollectiblePickup\b/, /\bEveryOneMinute\b|\bEveryTenMinutes\b|\bEveryHours\b/],
  quests: [/\bquest\b/i, /\bAdvancement\b/, /\bgiveExp\b/, /\bdaily\b/i],
  minigames: [/\barena\b/i, /\blobby\b/i, /\bcountdown\b/i, /\bspectator\b/i, /\bGameMode\.SPECTATOR\b/],
  economy: [/\bgetBalance\b|\bsetBalance\b|\bdepositPlayer\b|\bwithdrawPlayer\b/, /\bEconomics\b|\bServerRewards\b/, /\bcoins?\b/i, /\bbalance\b/i, /\bshop\b/i],
  admin: [/\bBanList\b|\bkickPlayer\b|\bsetBanned\b/, /\bOnPlayerBanned\b|\bServerUsers\b/, /\bmuted?\b/i, /\bclaim(s|ed)?\b/i, /\bvanish(ed)?\b/i],
  utility: [/\bteleport(Async)?\(/, /\b(set|get|del)Home\b/i, /\bwarp\b/i, /\bAsyncChatEvent\b|\bAsyncPlayerChatEvent\b/],
  interface: [/\bScoreboard\b|\bDisplaySlot\b/, /\bBossBar\b/, /\bcreateInventory\b|\bInventoryClickEvent\b|\bInventoryHolder\b/, /\bCuiHelper\b|\bCuiElementContainer\b/, /\bUIState\b|\bUserInterface\b/, /\bOnGUI\b|\bInventoryGui\b/, /\bISPanel\b|\bISUIElement\b|\bOnPreUIDraw\b/, /\bsendActionBar\b|\bshowTitle\b/, /\bTextDisplay\b/],
  visuals: [/\bspawnParticle\b|\bParticle\.[A-Z_]+/, /\bDust(Options|Transition)\b/, /\bFirework\b/, /\bShader\b|\bPostProcess\b|\bColorGrade\b/, /\bLightSource\b/],
  audio: [/\bplaySound\b/, /\bSoundEvent\b|\bSoundStyle\b|\bSoundEngine\b/, /\bAudioSource\b|\bAudioClip\b/, /\bgetSoundManager\b|\bplaySoundImpl\b/],
  performance: [/\bgetTPS\b|\bMSPT\b/, /\bChunkUnloadEvent\b|\bunloadChunk\b/, /\bmaxEntities\b|\bEntityLimit\b|\bentity[-_ ]?limit\b/i, /\bclear[-_ ]?lag\b|\bItemDespawnEvent\b|\bItemMergeEvent\b/i, /\bsetViewDistance\b|\bsetSimulationDistance\b/, /\bGC\.Collect\b|\bfreeMemory\b/],
};

/** Command names that say a lot on their own. */
const COMMAND_SIGNALS: [RegExp, CyrusCategoryId][] = [
  [/^\/?(pay|bal|balance|baltop|money|eco|shop|sell|buy|auction|ah|bank|bounty)$/i, "economy"],
  [/^\/?(home|sethome|delhome|homes|spawn|setspawn|tpa|tpaccept|tpdeny|tp|tphere|warp|setwarp|back|heal|feed|fly|kit|afk|nick|msg|r|reply|discord|rules|website|motd|sort|trash)$/i, "utility"],
  [/^\/?(ban|tempban|unban|kick|mute|unmute|warn|jail|vanish|v|freeze|staff|report|claim|unclaim|trust|untrust|region|rg|whitelist|invsee|spy|socialspy|audit)$/i, "admin"],
  [/^\/?(arena|spleef|duel|join|leave|lobby|ctf|koth|race|tournament|bedwars|skywars)$/i, "minigames"],
  [/^\/?(quest|quests|daily|dailies|achievements?|rankup|prestige|level|rewards?|streak)$/i, "quests"],
  [/^\/?(lag|tps|clearlag|lagg|entities|perf|optimi[sz]e)$/i, "performance"],
  [/^\/?(boss|summon|spawnmob|pet|pets|tame)$/i, "creatures"],
  [/^\/?(scoreboard|sb|hud|menu|gui|board|tab)$/i, "interface"],
  [/^\/?(particles?|trails?|cosmetics?|glow|wings|hat)$/i, "visuals"],
  [/^\/?(music|sound|radio|jukebox)$/i, "audio"],
];

export type AutoSortInput = {
  /** The original request. */
  prompt?: string | null;
  /** Follow-up change requests (each version's ask). */
  changes?: (string | null | undefined)[];
  title?: string | null;
  /** Build summary: tagline + text + how to use. */
  summary?: string | null;
  commands?: { usage: string; description?: string; permission?: string }[];
  permissions?: { node: string; description?: string }[];
  config?: { key: string; description?: string }[];
  /** Generated source (path + content). Only the first ~200 KB is read. */
  files?: { path: string; content: string }[];
  /** Restrict the answer to what this game supports (categoriesForGame). */
  allowed?: readonly CyrusCategoryId[];
};

export type AutoSortResult = {
  primary: CyrusCategoryId;
  secondary: CyrusCategoryId[];
  /** 0..1, how far ahead the primary is and how much evidence there was. */
  confidence: number;
  /** False when the evidence was thin: the UI asks the owner to confirm instead of guessing. */
  confident: boolean;
  /** Human-readable evidence per category ("prompt: sword", "command: /pay", "code: BossBar"). */
  why: Partial<Record<CyrusCategoryId, string[]>>;
  scores: Record<CyrusCategoryId, number>;
};

const W = { title: 2.2, prompt: 1.6, change: 0.6, summary: 1.2, meta: 1.0, command: 4, code: 2.5 } as const;
const MAX_CODE = 200_000;

/** Deterministic, zero-API classification of a finished mod. */
export function autoSort(input: AutoSortInput): AutoSortResult {
  const scores = Object.fromEntries(ALL.map((c) => [c, 0])) as Record<CyrusCategoryId, number>;
  const why: Partial<Record<CyrusCategoryId, string[]>> = {};
  const note = (c: CyrusCategoryId, s: string) => {
    const list = (why[c] ??= []);
    if (list.length < 6 && !list.includes(s)) list.push(s);
  };
  const addText = (text: string | null | undefined, weight: number, label: string) => {
    if (!text?.trim()) return;
    const p = text.toLowerCase();
    for (const c of CYRUS_CATEGORIES) {
      for (const k of c.keywords) {
        const n = countWord(p, k);
        if (!n) continue;
        scores[c.id] += Math.min(n, 3) * weight * (k.length >= 8 ? 1.5 : k.length >= 5 ? 1.2 : 1);
        note(c.id, `${label}: ${k}`);
      }
    }
  };

  addText(input.title, W.title, "title");
  addText(input.prompt, W.prompt, "prompt");
  for (const ch of input.changes ?? []) addText(ch, W.change, "change");
  addText(input.summary, W.summary, "summary");
  for (const c of input.commands ?? []) {
    const name = c.usage.trim().split(/\s+/)[0] ?? "";
    for (const [re, cat] of COMMAND_SIGNALS) {
      if (re.test(name)) { scores[cat] += W.command; note(cat, `command: ${name}`); break; }
    }
    addText(c.description, W.meta, "command");
  }
  for (const p of input.permissions ?? []) addText(`${p.node.replace(/[._]/g, " ")} ${p.description ?? ""}`, W.meta * 0.5, "permission");
  for (const c of input.config ?? []) addText(`${c.key.replace(/[._-]/g, " ")} ${c.description ?? ""}`, W.meta * 0.6, "config");

  let budget = MAX_CODE;
  for (const f of input.files ?? []) {
    if (budget <= 0) break;
    if (!/\.(java|kt|cs|lua|ya?ml|json|toml|properties)$/i.test(f.path)) continue;
    const src = f.content.slice(0, budget);
    budget -= src.length;
    for (const c of ALL) {
      for (const re of CODE_SIGNALS[c]) {
        if (re.test(src)) {
          scores[c] += W.code;
          note(c, `code: ${re.source.replace(/\\b|\\/g, "").slice(0, 32)}`);
        }
      }
    }
  }

  const allowed = input.allowed && input.allowed.length ? input.allowed : ALL;
  // Evidence for a category this game doesn't have moves to the nearest one it does.
  for (const c of ALL) {
    if (allowed.includes(c) || scores[c] <= 0) continue;
    const near = nearestAvailable(c, allowed);
    scores[near] += scores[c] * 0.8;
    note(near, `(${CYRUS_CATEGORY[c].label} isn't a category on this game)`);
    scores[c] = 0;
  }
  const ranked = ALL.filter((c) => allowed.includes(c)).sort((a, b) => scores[b] - scores[a] || ALL.indexOf(a) - ALL.indexOf(b));
  const s1 = scores[ranked[0]] ?? 0;
  const s2 = scores[ranked[1]] ?? 0;
  if (s1 <= 0) {
    const fallback = allowed.includes("gameplay") ? "gameplay" : ranked[0];
    return { primary: fallback, secondary: [], confidence: 0, confident: false, why, scores };
  }
  const secondary = ranked.slice(1, 3).filter((c) => scores[c] >= Math.max(2.5, s1 * 0.35));
  const lead = (s1 - s2) / s1; // 0 = tie, 1 = nothing else
  const evidence = Math.min(1, s1 / 12);
  const confidence = Math.round((0.55 * lead + 0.45 * evidence) * 100) / 100;
  return { primary: ranked[0], secondary, confidence, confident: confidence >= 0.3 && s1 >= 3, why, scores };
}

/** Back-compat for v4 callers: the single best category of a title + text. */
export function classifyMod(parts: { title?: string | null; text?: string | null }): CyrusCategoryId {
  return autoSort({ title: parts.title, prompt: parts.text }).primary;
}

