// Cyrus v6: the LISTING contract for a mod (PURE, client-safe). Shared by the studio's listing
// dialog (routing agent), the NxLabs page/storage (community agent: saveModListing) and the mod
// store. The studio calls storage only through lib/cyrus/listing-client.ts.
//
// A listing is what the world sees: title, primary + secondary universal category
// (lib/cyrus/categories.ts), an icon and a short description. Long description, gallery, links,
// changelog and visibility live on the NxLabs page (community agent) and extend this type there.

import { CYRUS_CATEGORY, normalizeCategory, type AutoSortResult, type CyrusCategoryId } from "./categories";

export type ModListingInput = {
  title: string;
  categoryId: CyrusCategoryId;
  /** Up to two, never containing categoryId. */
  secondaryCategoryIds: CyrusCategoryId[];
  /**
   * null = the default icon (the category glyph). Otherwise one of:
   *  - "glyph:<categoryId>"  a preset category glyph
   *  - "glyph:mono"          a generated monogram (initials of the title on the mod's colour)
   *  - "local:<rootId>"      an uploaded icon kept on the project until NxLabs storage takes it
   *  - "<assetId>"           an asset in the NxLabs (community) store, [A-Za-z0-9_-]{6,64}
   */
  iconAssetId: string | null;
  /** Brief description, plain text, up to LISTING_DESCRIPTION_MAX characters. */
  description: string;
};

/** Where the category came from; the dialog shows "auto-sorted" until the owner overrides it. */
export type ListingCategorySource = "auto" | "owner";

export const LISTING_TITLE_MIN = 2;
export const LISTING_TITLE_MAX = 60; // = lib/cyrus/meta.ts CYRUS_TITLE_MAX
export const LISTING_DESCRIPTION_MAX = 280;
export const LISTING_SECONDARY_MAX = 2;
/** Uploaded icons are re-encoded in the browser to this square size before upload. */
export const LISTING_ICON_PX = 128;
/** Max bytes of an inline (local:) icon data URL kept on a project. */
export const LISTING_ICON_INLINE_MAX = 24_000;

export type ListingField = keyof ModListingInput;
export type ListingErrors = Partial<Record<ListingField, string>>;

const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g;
const ICON_RE = /^(glyph:(mono|[a-z]+)|local:[A-Za-z0-9_-]{1,64}|[A-Za-z0-9_-]{6,64})$/;

export const cleanTitle = (s: string) => s.replace(CONTROL, "").replace(/\s+/g, " ").trim();
export const cleanDescription = (s: string) => s.replace(CONTROL, "").replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();

export function isIconRef(v: unknown): v is string {
  if (typeof v !== "string" || !ICON_RE.test(v)) return false;
  if (v.startsWith("glyph:") && v !== "glyph:mono") return !!normalizeCategory(v.slice(6)) && v.slice(6) in CYRUS_CATEGORY;
  return true;
}

/**
 * Validate anything (form state, a request body) into a clean ModListingInput.
 * Returns field errors in customer voice; never throws.
 */
export function validateListing(raw: unknown): { ok: true; value: ModListingInput } | { ok: false; errors: ListingErrors } {
  const errors: ListingErrors = {};
  const r = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;

  const title = typeof r.title === "string" ? cleanTitle(r.title) : "";
  if (title.length < LISTING_TITLE_MIN) errors.title = "Give your mod a name.";
  else if (title.length > LISTING_TITLE_MAX) errors.title = `Keep the name under ${LISTING_TITLE_MAX} characters.`;

  const categoryId = normalizeCategory(r.categoryId);
  if (!categoryId) errors.categoryId = "Pick a category.";

  const secRaw = Array.isArray(r.secondaryCategoryIds) ? r.secondaryCategoryIds : [];
  const secondary: CyrusCategoryId[] = [];
  for (const s of secRaw) {
    const c = normalizeCategory(s);
    if (c && c !== categoryId && !secondary.includes(c)) secondary.push(c);
  }
  if (secondary.length > LISTING_SECONDARY_MAX) errors.secondaryCategoryIds = `Pick up to ${LISTING_SECONDARY_MAX} extra categories.`;

  let iconAssetId: string | null = null;
  if (r.iconAssetId !== null && r.iconAssetId !== undefined && r.iconAssetId !== "") {
    if (isIconRef(r.iconAssetId)) iconAssetId = r.iconAssetId;
    else errors.iconAssetId = "That icon couldn't be used. Pick another one.";
  }

  const description = typeof r.description === "string" ? cleanDescription(r.description) : "";
  if (description.length > LISTING_DESCRIPTION_MAX) errors.description = `Keep the description under ${LISTING_DESCRIPTION_MAX} characters.`;

  if (Object.keys(errors).length || !categoryId) return { ok: false, errors };
  return { ok: true, value: { title, categoryId, secondaryCategoryIds: secondary, iconAssetId, description } };
}

/** Shorten to `max` characters at a sentence, else a word boundary (adds an ellipsis when cut). */
export function clip(text: string, max = LISTING_DESCRIPTION_MAX): string {
  const t = cleanDescription(text).replace(/\s*\n+\s*/g, " ");
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  const sentence = cut.lastIndexOf(". ");
  if (sentence >= max * 0.5) return cut.slice(0, sentence + 1);
  const word = cut.lastIndexOf(" ");
  return `${cut.slice(0, word > max * 0.6 ? word : max - 1).replace(/[\s,;:.-]+$/, "")}…`;
}

/**
 * A free first draft of the description from what the build already reported (no model call):
 * the tagline, then the summary text, then how to use, clipped to 280 characters. Falls back to
 * the prompt, rewritten from "make me a..." into a statement.
 */
export function draftDescription(src: { tagline?: string | null; text?: string | null; howToUse?: string[] | null; prompt?: string | null }): string {
  const parts: string[] = [];
  const tag = src.tagline?.trim();
  const text = src.text?.trim();
  if (tag && !(text && text.toLowerCase().startsWith(tag.toLowerCase()))) parts.push(/[.!?]$/.test(tag) ? tag : `${tag}.`);
  if (text) parts.push(text);
  if (!text && src.howToUse?.length) parts.push(src.howToUse.slice(0, 2).join(" "));
  let out = parts.join(" ").trim();
  if (!out && src.prompt) {
    out = src.prompt
      .replace(/\s+/g, " ")
      .trim()
      .replace(/^(please\s+)?(can you\s+|could you\s+)?(make|create|build|forge|generate|write|give)( me| us)?\s+/i, "")
      .replace(/^(a|an)\s+(minecraft\s+)?(paper\s+)?(plugin|mod)\s*[:,-]?\s*/i, "");
    out = out ? out[0].toUpperCase() + out.slice(1) : "";
    if (out && !/[.!?]$/.test(out)) out += ".";
  }
  return clip(out);
}

/** The dialog's starting values for a mod, from its current name, the auto-sorter and the build summary. */
export function draftListing(args: {
  title: string;
  sort: Pick<AutoSortResult, "primary" | "secondary">;
  saved?: Partial<ModListingInput> | null;
  summary?: Parameters<typeof draftDescription>[0];
}): ModListingInput {
  const s = args.saved ?? {};
  const categoryId = normalizeCategory(s.categoryId) ?? args.sort.primary;
  const secondary = (s.secondaryCategoryIds ?? args.sort.secondary).map(normalizeCategory).filter((c): c is CyrusCategoryId => !!c && c !== categoryId).slice(0, LISTING_SECONDARY_MAX);
  return {
    title: cleanTitle(s.title || args.title).slice(0, LISTING_TITLE_MAX),
    categoryId,
    secondaryCategoryIds: secondary,
    iconAssetId: s.iconAssetId && isIconRef(s.iconAssetId) ? s.iconAssetId : null,
    description: s.description !== undefined ? clip(s.description) : draftDescription(args.summary ?? {}),
  };
}

/** Initials for the generated monogram icon ("Frost Axe" -> "FA", "CoinShop" -> "CS"). */
export function monogram(title: string): string {
  const words = title.replace(/([a-z])([A-Z])/g, "$1 $2").match(/[A-Za-z0-9]+/g) ?? [];
  const sig = words.filter((w) => !/^(the|a|an|of|and|for|mod|plugin|v\d+)$/i.test(w));
  const use = sig.length ? sig : words;
  return (use.length >= 2 ? use[0][0] + use[1][0] : (use[0] ?? "C").slice(0, 2)).toUpperCase();
}

