// Cyrus v6: broad-request prompt ROUTING (PURE, client-safe, zero API calls).
//
// The dock no longer needs a hovered game or mod. Anything typed anywhere ("make me a mod for
// Minecraft where creepers drop diamonds", "work on my frost axe mod and fix the cooldown",
// "add a shop command to my Rust plugin", "what mods do I have for Valheim", "update the boss
// mod for the new version") becomes a RouteDecision: what to do, on which game, in which
// universal category, on which of the user's projects.
//
// Cost-aware by design: a deterministic fast path decides almost everything instantly in the
// browser (game aliases + typo-tolerant matching, "my <name> mod" fuzzy-matched against the
// user's own projects, intent verbs, category keywords). When the input is genuinely ambiguous
// it does NOT call a model: it returns `clarify` with one-tap options ("Frost Axe v2 or Frost
// Axe?", "Which game is this for?"). The current selection (and hover) always wins as context.
// Unit-tested in test/cyrus-route.test.ts.

import { CYRUS_CATEGORY, bestCategory, categoriesForGame, toCategory, type CyrusCategoryId } from "./categories";

export type RouteIntent = "create" | "refine" | "fix" | "explain" | "install" | "browse" | "unknown";

export type RouteDecision = {
  intent: RouteIntent;
  /** The game the request lands on (null = not known yet: see clarify). */
  gameId: string | null;
  /** Universal category (create: where the new mod goes; others: the project's). */
  categoryId: CyrusCategoryId | null;
  /** The studio mod id of the target project (refine/fix/explain/install). */
  projectId?: string;
  /** 0..1. Below ~0.5 the dock shows the decision as a suggestion rather than acting on it. */
  confidence: number;
  /** One line in customer voice for the dock chip: "Creating a new Minecraft mod in Weapons". */
  reason: string;
  /** Present when one tap from the user is needed. Each option is a complete decision. */
  clarify?: { question: string; options: RouteOption[] };
  /** A game the user named that Cyrus doesn't build for. */
  unsupported?: string;
  /** What decided it (for tests and the dock's wording). */
  via: "selection" | "prompt" | "project" | "default";
};

export type RouteOption = { label: string; hint?: string; decision: RouteDecision };

export type RouteGame = { id: string; name: string; short?: string; aliases: string[]; real?: boolean };

export type RouteProject = {
  /** Studio mod id ("nx-<rootId>" for real projects, the local id for template mods). */
  id: string;
  gameId: string;
  categoryId: CyrusCategoryId | string;
  title: string;
  /** Other names it goes by (the plugin name, an old title). */
  aliases?: string[];
  /** ms epoch, newest wins ties. */
  updatedAt?: number;
};

export type RouteSelection = { level: "core" | "game" | "category" | "mod"; gameId?: string; category?: string; modId?: string };

export type RouteContext = {
  selection?: RouteSelection;
  /** What the pointer is over right now (counts like a selection when nothing is selected). */
  hover?: { gameId?: string; modId?: string };
};

export type RouteWorld = { games: RouteGame[]; projects: RouteProject[] };

/* ───────────── Text helpers ───────────── */

export function normalizeText(s: string): string {
  return s
    .toLowerCase()
    .replace(/[\u2018\u2019\u201b`]/g, "'")
    .replace(/[\u201c\u201d"]/g, " ")
    .replace(/'s\b/g, "")
    .replace(/[^a-z0-9'\s/-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const tokens = (s: string) => normalizeText(s).split(/[\s/-]+/).filter(Boolean);

/** Damerau-Levenshtein distance with an early exit above `max`. */
export function editDistance(a: string, b: string, max = 3): number {
  if (a === b) return 0;
  if (Math.abs(a.length - b.length) > max) return max + 1;
  const d: number[][] = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    let rowMin = Infinity;
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
      rowMin = Math.min(rowMin, d[i][j]);
    }
    if (rowMin > max) return max + 1;
  }
  return d[a.length][b.length];
}

/** Typo budget for a word: none under 5 letters (rust/trust), 1 up to 7, 2 beyond. */
const typoBudget = (w: string) => (w.length < 5 ? 0 : w.length <= 7 ? 1 : 2);
const fuzzyEq = (a: string, b: string) => a === b || (a[0] === b[0] && editDistance(a, b, 2) <= Math.min(typoBudget(a), typoBudget(b)));

/* ───────────── Games ───────────── */

/** Names people use for games Cyrus does not build for (so we can say so plainly). */
const UNSUPPORTED: [string, string][] = [
  ["ark", "ARK"], ["ark survival", "ARK"], ["the isle", "The Isle"], ["skyrim", "Skyrim"], ["fallout", "Fallout"], ["gta", "GTA"],
  ["grand theft auto", "GTA"], ["fivem", "FiveM"], ["fortnite", "Fortnite"], ["roblox", "Roblox"], ["stardew", "Stardew Valley"],
  ["stardew valley", "Stardew Valley"], ["cyberpunk", "Cyberpunk 2077"], ["factorio", "Factorio"], ["7 days to die", "7 Days to Die"],
  ["7dtd", "7 Days to Die"], ["satisfactory", "Satisfactory"], ["garry mod", "Garry's Mod"], ["gmod", "Garry's Mod"],
  ["counter strike", "Counter-Strike"], ["cs2", "Counter-Strike 2"], ["csgo", "Counter-Strike"], ["space engineers", "Space Engineers"],
  ["conan exiles", "Conan Exiles"], ["dayz", "DayZ"], ["v rising", "V Rising"], ["enshrouded", "Enshrouded"],
  ["sons of the forest", "Sons of the Forest"], ["unturned", "Unturned"], ["among us", "Among Us"], ["league of legends", "League of Legends"],
  ["elden ring", "Elden Ring"], ["baldur gate", "Baldur's Gate 3"], ["bg3", "Baldur's Gate 3"], ["the sims", "The Sims"], ["sims 4", "The Sims 4"],
  ["bedrock", "Minecraft Bedrock"], ["bedrock edition", "Minecraft Bedrock"], ["pocket edition", "Minecraft Bedrock"],
];

type GameHit = { id: string; score: number; strong: boolean; word: string };

/** Strong names: the game's name, short name, id and its first two aliases. The rest are content words. */
function gameNames(g: RouteGame): { strong: string[]; weak: string[] } {
  const strong = [...new Set([g.name, g.short ?? "", g.id, ...g.aliases.slice(0, 2)].map(normalizeText).filter(Boolean))];
  const weak = g.aliases.slice(2).map(normalizeText).filter((a) => a && !strong.includes(a));
  return { strong, weak };
}

function phraseIn(text: string, toks: string[], phrase: string, fuzzy: boolean): boolean {
  const pt = phrase.split(" ");
  if (pt.length > 1) {
    if ((" " + text + " ").includes(" " + phrase + " ")) return true;
    if (!fuzzy) return false;
    for (let i = 0; i + pt.length <= toks.length; i++) if (pt.every((p, k) => fuzzyEq(toks[i + k], p))) return true;
    return false;
  }
  return toks.some((t) => t === phrase || t === phrase + "s" || (fuzzy && fuzzyEq(t, phrase)));
}

export function detectGames(text: string, games: RouteGame[]): GameHit[] {
  const t = normalizeText(text);
  const toks = tokens(text);
  const hits: GameHit[] = [];
  for (const g of games) {
    const { strong, weak } = gameNames(g);
    let best: GameHit | null = null;
    for (const n of strong) {
      if (phraseIn(t, toks, n, false)) { best = { id: g.id, score: 3 + n.length / 100, strong: true, word: n }; break; }
    }
    if (!best) for (const n of strong) {
      if (n.length >= 5 && phraseIn(t, toks, n, true)) { best = { id: g.id, score: 2.5, strong: true, word: n }; break; }
    }
    if (!best) for (const n of weak) {
      if (phraseIn(t, toks, n, false)) { best = { id: g.id, score: 1, strong: false, word: n }; break; }
    }
    if (best) hits.push(best);
  }
  return hits.sort((a, b) => b.score - a.score);
}

function detectUnsupported(text: string): string | null {
  const t = normalizeText(text);
  const toks = tokens(text);
  for (const [n, label] of UNSUPPORTED) if (phraseIn(t, toks, n, n.length >= 7)) return label;
  return null;
}

/* ───────────── Intent ───────────── */

const RE = {
  browse: /\b(what|which)\b.*\b(mods?|plugins?)\b.*\b(have|got|made|built|own)\b|\b(show|list|see|view|open|find)\s+(me\s+)?(all\s+)?(of\s+)?my\s+(\w+\s+)?(mods|plugins|projects)\b|^(my\s+)?(\w+\s+)?(mods|plugins|projects)\s*\??$|\btake me to\b|\bgo to\b/,
  install: /\b(install|deploy|reinstall|uninstall|enable|disable|activate|deactivate)\b|\bturn\s+(it\s+)?(on|off)\b|\b(put|push|upload|load|add|send)\b.*\b(on|to|onto|into)\s+(my\s+|the\s+)?(\w+\s+)?(server|servers)\b/,
  explain: /^(what|how|why|explain|describe|tell me|walk me through)\b|\b(explain|what does|how does|how do i use|how do i|what is|tell me about|walk me through|break down)\b/,
  fix: /\b(fix|fixes|fixing|bug|bugs|buggy|broken|breaks|crash|crashes|crashing|errors?|not working|doesn'?t work|does not work|isn'?t working|won'?t|stopped working|fails?|failing|glitch\w*|repair|debug|issue|problem|wrong)\b/,
  refine: /\b(add|adds|change|tweak|adjust|update|upgrade|improve|increase|decrease|reduce|raise|lower|make it|make the|make them|rename|remove|delete|replace|edit|modify|work on|rework|polish|balance|rebalance|extend|also|port|support|speed up|slow down|double|halve|nerf|buff|continue)\b/,
  create: /\b(make|create|build|forge|generate|write|give|design|new|i want|i need|i'd like|can you|code up|start)\b/,
  newMod: /\b(new|another|separate|fresh)\s+(\w+\s+)?(mod|plugin|addon|project)\b|\bfrom scratch\b/,
  version: /\b(new|latest|current|next)\s+(game\s+|minecraft\s+|server\s+)?(version|update|patch|build)\b|\b\d+\.\d+(\.\d+)?\b|\bbuild 4[12]\b/,
};

/* ───────────── Project matching ───────────── */

const NAME_STOP = new Set(["the", "a", "an", "my", "our", "this", "that", "mod", "plugin", "addon", "script", "pack", "project", "for", "of", "and", "to", "in", "on", "with", "new", "old", "current"]);
const VERSION_TOKEN = /^v?\d+$/;
const sig = (toks: string[]) => toks.filter((t) => !NAME_STOP.has(t) && !VERSION_TOKEN.test(t));
const titleTokens = (s: string) => sig(tokens(s.replace(/([a-z0-9])([A-Z])/g, "$1 $2")));

/** "my frost axe mod", "the boss plugin", "my Rust plugin": the words between the determiner and "mod". */
export function namedReference(text: string): { words: string[]; generic: boolean } | null {
  const t = normalizeText(text);
  const m = t.match(/\b(my|our|the|this|that)\s+((?:[a-z0-9'-]+\s+){0,6}?)(mod|mods|plugin|plugins|addon|script|datapack|pack|project)\b/);
  if (!m) return null;
  const words = sig(m[2].trim().split(/\s+/).filter(Boolean));
  return { words, generic: m[1] === "my" || m[1] === "our" };
}

function tokenOverlap(phrase: string[], title: string[]): number {
  if (!phrase.length || !title.length) return 0;
  let hit = 0;
  for (const p of phrase) if (title.some((t) => fuzzyEq(p, t) || (p.length >= 4 && t.startsWith(p)))) hit++;
  // every phrase word should be in the title; extra title words cost a little
  return (hit / phrase.length) * (0.75 + 0.25 * Math.min(1, phrase.length / title.length));
}

type ProjectHit = { p: RouteProject; score: number };

function matchProjects(words: string[], projects: RouteProject[]): ProjectHit[] {
  return projects
    .map((p) => ({ p, score: Math.max(tokenOverlap(words, titleTokens(p.title)), ...(p.aliases ?? []).map((a) => tokenOverlap(words, titleTokens(a)))) }))
    .filter((h) => h.score >= 0.5)
    .sort((a, b) => b.score - a.score || (b.p.updatedAt ?? 0) - (a.p.updatedAt ?? 0));
}

/** A project whose whole title appears in the text, without "my ... mod" around it. */
function implicitProjects(text: string, projects: RouteProject[]): ProjectHit[] {
  const toks = sig(tokens(text));
  return projects
    .map((p) => {
      const tt = titleTokens(p.title);
      if (!tt.length || !tt.some((t) => t.length >= 4)) return { p, score: 0 };
      const all = tt.every((t) => toks.some((x) => fuzzyEq(x, t)));
      return { p, score: all ? 0.9 + Math.min(0.09, tt.length * 0.03) : 0 };
    })
    .filter((h) => h.score > 0)
    .sort((a, b) => b.score - a.score || (b.p.updatedAt ?? 0) - (a.p.updatedAt ?? 0));
}

/* ───────────── The router ───────────── */

const gameName = (games: RouteGame[], id: string | null) => games.find((g) => g.id === id)?.name ?? "this game";
const catLabel = (c: CyrusCategoryId | null) => (c ? CYRUS_CATEGORY[c].label : null);

function describe(d: Omit<RouteDecision, "reason">, world: RouteWorld, title?: string): string {
  const g = gameName(world.games, d.gameId);
  switch (d.intent) {
    case "create": return d.gameId ? `Creating a new ${g} mod${d.categoryId ? ` in ${catLabel(d.categoryId)}` : ""}` : "Creating a new mod";
    case "refine": return `Refining ${title ?? "this mod"}`;
    case "fix": return `Fixing ${title ?? "this mod"}`;
    case "explain": return `Explaining ${title ?? "this mod"}`;
    case "install": return `Installing ${title ?? "this mod"} on a server`;
    case "browse": return d.gameId ? `Showing your ${g} mods` : "Showing all your mods";
    default: return "Tell Cyrus which game or mod this is for";
  }
}

function decide(d: Omit<RouteDecision, "reason"> & { reason?: string }, world: RouteWorld, title?: string): RouteDecision {
  return { ...d, reason: d.reason ?? describe(d, world, title) };
}

/** A create decision on `gameId`, category from the text (falling back to `fallbackCat`). */
function createOn(gameId: string, text: string, world: RouteWorld, fallbackCat: string | undefined, confidence: number, via: RouteDecision["via"]): RouteDecision {
  const allowed = categoriesForGame(gameId);
  const cat = bestCategory(text, allowed)?.id ?? (fallbackCat ? toCategory(fallbackCat) : null);
  return decide({ intent: "create", gameId, categoryId: cat, confidence, via }, world);
}

function projectDecision(intent: RouteIntent, p: RouteProject, world: RouteWorld, confidence: number, via: RouteDecision["via"], text: string): RouteDecision {
  const versionBump = intent === "refine" && RE.version.test(normalizeText(text)) && /\bupdate|upgrade|port\b/.test(normalizeText(text));
  return decide({
    intent, gameId: p.gameId, categoryId: toCategory(p.categoryId), projectId: p.id, confidence, via,
    ...(versionBump ? { reason: `Updating ${p.title} for the new version` } : {}),
  }, world, p.title);
}

function pickIntent(t: string, hasTarget: boolean): RouteIntent {
  if (RE.browse.test(t)) return "browse";
  if (RE.install.test(t)) return "install";
  if (RE.fix.test(t)) return "fix";
  // "how do I…/what does…" is a question; "what if it also…" is a change
  if (RE.explain.test(t) && !/\b(make|add|create|build|forge)\b/.test(t)) return "explain";
  if (hasTarget && RE.refine.test(t)) return "refine";
  if (RE.create.test(t)) return "create";
  if (hasTarget) return "refine";
  return "create";
}

/**
 * Decide where a free-text request goes. Pure and instant.
 * `world.projects` should be the user's own mods (real projects + local template mods), not idea seeds.
 */
export function routeRequest(text: string, ctx: RouteContext, world: RouteWorld): RouteDecision {
  const t = normalizeText(text);
  const sel = ctx.selection ?? { level: "core" };
  const hover = sel.level === "core" ? ctx.hover : undefined;
  const ctxGame = sel.gameId ?? hover?.gameId;
  const ctxModId = sel.level === "mod" ? sel.modId : hover?.modId;
  const ctxMod = ctxModId ? world.projects.find((p) => p.id === ctxModId) : undefined;
  const supported = world.games;

  if (!t) {
    if (ctxMod) return projectDecision("refine", ctxMod, world, 0.3, "selection", "");
    return decide({ intent: "unknown", gameId: ctxGame ?? null, categoryId: sel.category ? toCategory(sel.category) : null, confidence: 0, via: "default", reason: "Describe a mod, or ask about one of yours" }, world);
  }

  const gameHits = detectGames(text, supported);
  const strongGames = gameHits.filter((h) => h.strong);
  const namedGame = strongGames[0]?.id ?? null;
  const unsupported = strongGames.length ? null : detectUnsupported(text);

  // ── which project does the text point at? ──
  const ref = namedReference(text);
  const refWords = ref ? ref.words.filter((w) => !gameHits.some((h) => h.word.split(" ").includes(w)) && !supported.some((g) => fuzzyEq(w, normalizeText(g.id)) || fuzzyEq(w, normalizeText(g.name)))) : [];
  const scope = (list: RouteProject[]) => (namedGame ? list.filter((p) => p.gameId === namedGame) : list);
  let hits: ProjectHit[] = [];
  let generic = false;
  if (ref && refWords.length) hits = matchProjects(refWords, scope(world.projects));
  else if (ref?.generic) generic = true; // "my mod", "my Rust plugin"
  if (!hits.length && !generic) hits = implicitProjects(text, scope(world.projects));
  const explicitNew = RE.newMod.test(t);
  const hasTarget = !explicitNew && (hits.length > 0 || generic || !!ctxMod);
  const intent = pickIntent(t, hasTarget);

  // ── unsupported game named ──
  if (unsupported && intent !== "browse") {
    const options: RouteOption[] = supported.map((g) => ({ label: g.name, hint: g.real ? "Builds for real" : "Template preview", decision: createOn(g.id, text, world, undefined, 0.8, "prompt") }));
    return decide({
      intent: "unknown", gameId: null, categoryId: bestCategory(text)?.id ?? null, confidence: 0.9, via: "prompt", unsupported,
      reason: `Cyrus doesn't build ${unsupported} mods yet`,
      clarify: { question: `Cyrus builds for ${supported.map((g) => g.name).join(", ").replace(/, ([^,]*)$/, " and $1")}. Pick one to continue:`, options },
    }, world);
  }

  // ── several games named: ask which one first ──
  if (strongGames.length > 1 && !hits.length && intent !== "browse") {
    const options = strongGames.slice(0, 4).map((h) => ({ label: gameName(supported, h.id), decision: createOn(h.id, text, world, undefined, 0.8, "prompt") }));
    return decide({ intent: "create", gameId: null, categoryId: bestCategory(text)?.id ?? null, confidence: 0.3, via: "prompt", reason: "This mentions more than one game", clarify: { question: "Which game is this mod for? (Each game gets its own mod.)", options } }, world);
  }

  // ── browse ──
  if (intent === "browse") {
    const gameId = namedGame ?? (gameHits[0]?.id ?? null) ?? null;
    return decide({ intent, gameId: gameId ?? (sel.level !== "core" ? ctxGame ?? null : null), categoryId: bestCategory(text)?.id ?? null, confidence: gameId ? 0.9 : 0.7, via: gameId ? "prompt" : "default" }, world);
  }

  // ── an explicit project reference ──
  if (hits.length) {
    const top = hits[0];
    const close = hits.filter((h) => h.score >= top.score - 0.08);
    if (close.length > 1) {
      const options = close.slice(0, 3).map((h) => ({ label: h.p.title, hint: gameName(supported, h.p.gameId), decision: projectDecision(intent === "create" ? "refine" : intent, h.p, world, 0.9, "project", text) }));
      return decide({ intent: intent === "create" ? "refine" : intent, gameId: top.p.gameId, categoryId: toCategory(top.p.categoryId), confidence: 0.4, via: "project", reason: `Which ${refWords.join(" ") || "mod"}?`, clarify: { question: `${options.map((o) => o.label).join(" or ")}?`, options } }, world);
    }
    return projectDecision(intent === "create" ? "refine" : intent, top.p, world, Math.min(0.97, 0.55 + top.score * 0.4), "project", text);
  }

  // ── "my mod" / "my Rust plugin" with no name ──
  if (generic && !explicitNew) {
    const mine = scope(world.projects).sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0));
    const inCtx = ctxMod && (!namedGame || ctxMod.gameId === namedGame) ? ctxMod : undefined;
    if (inCtx) return projectDecision(intent === "create" ? "refine" : intent, inCtx, world, 0.85, "selection", text);
    if (mine.length === 1) return projectDecision(intent === "create" ? "refine" : intent, mine[0], world, 0.8, "project", text);
    if (mine.length === 0) {
      const g = namedGame ?? ctxGame ?? null;
      const gName = g ? gameName(supported, g) : null;
      return decide({
        intent: "unknown", gameId: g, categoryId: null, confidence: 0.5, via: "default",
        reason: gName ? `You don't have a ${gName} mod yet` : "You don't have any mods yet",
        clarify: g ? { question: `Create a new ${gName} mod from this instead?`, options: [{ label: `New ${gName} mod`, decision: createOn(g, text, world, undefined, 0.8, "prompt") }] } : undefined,
      }, world);
    }
    const i2 = intent === "create" ? "refine" : intent;
    const options = mine.slice(0, 3).map((p) => ({ label: p.title, hint: gameName(supported, p.gameId), decision: projectDecision(i2, p, world, 0.9, "project", text) }));
    return decide({ intent: i2, gameId: namedGame, categoryId: null, confidence: 0.3, via: "project", reason: "Which of your mods?", clarify: { question: namedGame ? `Which ${gameName(supported, namedGame)} mod?` : "Which of your mods?", options } }, world);
  }

  // ── the selected mod is the context ──
  if (ctxMod && !explicitNew && (!namedGame || namedGame === ctxMod.gameId)) {
    const i2 = intent === "create" ? "refine" : intent;
    return projectDecision(i2, ctxMod, world, sel.level === "mod" ? 0.92 : 0.7, "selection", text);
  }

  // ── a mod to explain/install/fix but no mod in sight ──
  if (intent === "explain" || intent === "install" || intent === "fix") {
    const mine = scope(world.projects).sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0)).slice(0, 3);
    if (mine.length) {
      const options = mine.map((p) => ({ label: p.title, hint: gameName(supported, p.gameId), decision: projectDecision(intent, p, world, 0.9, "project", text) }));
      return decide({ intent, gameId: namedGame ?? ctxGame ?? null, categoryId: null, confidence: 0.3, via: "default", reason: "Which mod do you mean?", clarify: { question: "Which mod do you mean?", options } }, world);
    }
    if (intent !== "fix") return decide({ intent: "unknown", gameId: namedGame ?? ctxGame ?? null, categoryId: null, confidence: 0.4, via: "default", reason: "You don't have any mods yet: describe one and Cyrus builds it" }, world);
    // "fix" with nothing to fix: treat as a new mod request ("fix the lag on my server" -> performance mod)
  }

  // ── a new mod ──
  if (namedGame) return createOn(namedGame, text, world, namedGame === ctxGame ? sel.category : undefined, strongGames[0].score >= 3 ? 0.92 : 0.8, "prompt");
  if (ctxGame && sel.level !== "core") return createOn(ctxGame, text, world, sel.category, 0.85, "selection");
  if (ctxGame) return createOn(ctxGame, text, world, undefined, 0.7, "selection"); // hover
  const weak = gameHits[0];
  const cat = bestCategory(text)?.id ?? null;
  const ordered = weak ? [weak.id, ...supported.map((g) => g.id).filter((id) => id !== weak.id)] : supported.map((g) => g.id);
  const options = ordered.map((id) => ({ label: gameName(supported, id), hint: supported.find((g) => g.id === id)?.real ? "Builds for real" : "Template preview", decision: createOn(id, text, world, undefined, 0.85, "prompt") }));
  return decide({
    intent: "create", gameId: weak?.id ?? null, categoryId: cat, confidence: weak ? 0.35 : 0.2, via: "default",
    reason: weak ? `Sounds like ${gameName(supported, weak.id)}` : "Which game is this for?",
    clarify: { question: weak ? `Is this for ${gameName(supported, weak.id)}?` : "Which game is this mod for?", options },
  }, world);
}

/** The dock acts on a decision without asking when there's nothing to clarify. */
export const needsClarify = (d: RouteDecision) => !!d.clarify && d.clarify.options.length > 0;

