describe("cyrus route: broad requests from anywhere", () => {
  it(`has at least 60 phrases (${CASES.length})`, () => assert.ok(CASES.length >= 60));
  for (const [text, ctx, want, w] of CASES) {
    it(`${JSON.stringify(text)}${ctx.selection?.level !== "core" || ctx.hover ? ` [${ctx.selection?.modId ?? ctx.selection?.gameId ?? ctx.hover?.gameId}]` : ""}${w === empty ? " [no projects]" : ""}`, () => {
      check(text, ctx, want, w ?? world);
    });
  }
  it("empty text keeps the context and decides nothing", () => {
    assert.equal(routeRequest("   ", core, world).intent, "unknown");
    assert.equal(routeRequest("", onMod("nx-shop"), world).projectId, "nx-shop");
  });
  it("is fast enough to run on every keystroke", () => {
    const t0 = performance.now();
    for (let i = 0; i < 200; i++) for (const [text, ctx] of CASES.slice(0, 20)) routeRequest(text, ctx, world);
    const per = (performance.now() - t0) / 4000;
    assert.ok(per < 2, `${per.toFixed(3)} ms per call`);
  });
  it("helpers: typo distance and named references", () => {
    assert.equal(editDistance("valhiem", "valheim"), 1);
    assert.equal(editDistance("minecarft", "minecraft"), 1);
    assert.ok(editDistance("trust", "rust") >= 1);
    assert.deepEqual(namedReference("work on my frost axe mod")?.words, ["frost", "axe"]);
    assert.deepEqual(namedReference("my Rust plugin")?.words, ["rust"]);
    assert.equal(namedReference("a sword"), null);
  });
  it("'trust' and 'must' never route to Rust", () => {
    const d = routeRequest("a trust system so players must vote", core, world);
    assert.notEqual(d.gameId, "rust");
  });
});

describe("cyrus universal categories", () => {
  it("are 14 to 16 presets, each with a unique id, label, blurb, accent and store bucket", () => {
    assert.ok(CYRUS_CATEGORIES.length >= 14 && CYRUS_CATEGORIES.length <= 16);
    assert.equal(new Set(CYRUS_CATEGORIES.map((c) => c.id)).size, CYRUS_CATEGORIES.length);
    assert.equal(new Set(CYRUS_CATEGORIES.map((c) => c.label)).size, CYRUS_CATEGORIES.length);
    for (const c of CYRUS_CATEGORIES) {
      assert.ok(c.blurb.length > 10 && c.blurb.length < 70, c.id);
      assert.match(c.rgb, /^\d{1,3} \d{1,3} \d{1,3}$/);
      assert.ok(c.keywords.length >= 8, c.id);
    }
    for (const id of ["environment", "weapons", "performance"]) assert.ok(CYRUS_CATEGORY_IDS.includes(id as never), id);
  });
  it("normalise every older id and plain words", () => {
    assert.equal(normalizeCategory("worlds"), "environment");
    assert.equal(normalizeCategory("worldgen"), "environment");
    assert.equal(normalizeCategory("characters"), "creatures");
    assert.equal(normalizeCategory("mechanics"), "gameplay");
    assert.equal(normalizeCategory("shaders"), "visuals");
    assert.equal(normalizeCategory("Economy & shops"), "economy");
    assert.equal(normalizeCategory("Admin & protection"), "admin");
    assert.equal(normalizeCategory("QoL"), "utility");
    assert.equal(normalizeCategory("nonsense"), null);
    assert.equal(toCategory("nonsense"), "gameplay");
    assert.equal(normalizeCategory("__proto__"), null);
  });
  it("map to a generator archetype (NPC words pick the character archetype)", () => {
    assert.equal(engineCategory("environment"), "worlds");
    assert.equal(engineCategory("economy"), "mechanics");
    assert.equal(engineCategory("creatures", "a trader npc who sells maps"), "characters");
    assert.equal(engineCategory("creatures", "a boss"), "creatures");
  });
  it("per game: GameSupport lists win, the default table otherwise", () => {
    assert.equal(categoriesForGame("minecraft").length, CYRUS_CATEGORIES.length);
    assert.ok(!categoriesForGame("rust").includes("magic"));
    assert.deepEqual(categoriesForGame("rust", { categories: ["weapons", "worlds", "bogus"] }), ["environment", "weapons"]);
    assert.equal(categoriesForGame("custom-thing").length, CYRUS_CATEGORIES.length);
    assert.equal(nearestAvailable("magic", categoriesForGame("rust")), "gameplay");
    assert.equal(nearestAvailable("visuals", ["audio", "gameplay"]), "audio");
  });
  it("every built-in game's starting branches are universal ids", () => {
    for (const g of GAMES) for (const c of g.categories) assert.ok(CYRUS_CATEGORY_IDS.includes(c), `${g.id}:${c}`);
  });
});

describe("cyrus auto-sorter (zero API)", () => {
  it("sorts from the prompt alone", () => {
    assert.equal(autoSort({ prompt: "A frost greatsword that freezes and slows enemies on critical hits" }).primary, "weapons");
    assert.equal(autoSort({ prompt: "A coin shop economy: coins for mob kills, /pay, /baltop and a chest menu shop" }).primary, "economy");
    assert.equal(autoSort({ prompt: "Clear lag: remove dropped items every 5 minutes and cap entities per chunk" }).primary, "performance");
  });
  it("commands and code count more than a stray word", () => {
    const r = autoSort({
      prompt: "A plugin for my friends",
      commands: [{ usage: "/sethome <name>" }, { usage: "/home" }, { usage: "/tpa <player>" }],
      files: [{ path: "src/main/java/a/Homes.java", content: "player.teleportAsync(loc); getHome(uuid)" }],
    });
    assert.equal(r.primary, "utility");
    assert.equal(r.confident, true);
    assert.ok(r.why.utility?.some((w) => w.startsWith("command:")));
  });
  it("gives up to two secondaries and never repeats the primary", () => {
    const r = autoSort({ prompt: "A spleef minigame arena with a sidebar scoreboard and coin rewards from a shop" });
    assert.ok(r.secondary.length <= 2);
    assert.ok(!r.secondary.includes(r.primary));
  });
  it("says when it isn't sure (the dialog asks instead of guessing)", () => {
    const r = autoSort({ prompt: "qqq zzz" });
    assert.equal(r.confident, false);
    assert.equal(r.primary, "gameplay");
  });
  it("respects what the game supports", () => {
    const r = autoSort({ prompt: "a fireball spell with mana", allowed: categoriesForGame("rust") });
    assert.ok(categoriesForGame("rust").includes(r.primary));
  });
});

describe("cyrus listing contract", () => {
  it("validates and cleans", () => {
    const ok = validateListing({ title: "  Frost   Axe ", categoryId: "worlds", secondaryCategoryIds: ["weapons", "worlds", "weapons", "bogus"], iconAssetId: "glyph:weapons", description: "A cold one.\u0007" });
    assert.ok(ok.ok);
    if (ok.ok) {
      assert.equal(ok.value.title, "Frost Axe");
      assert.equal(ok.value.categoryId, "environment");
      assert.deepEqual(ok.value.secondaryCategoryIds, ["weapons"]);
      assert.equal(ok.value.description, "A cold one.");
    }
    const bad = validateListing({ title: "x", categoryId: "nope", iconAssetId: "../../etc", description: "y".repeat(LISTING_DESCRIPTION_MAX + 1) });
    assert.ok(!bad.ok);
    if (!bad.ok) assert.deepEqual(Object.keys(bad.errors).sort(), ["categoryId", "description", "iconAssetId", "title"]);
  });
  it("icon references", () => {
    for (const ok of ["glyph:weapons", "glyph:mono", "local:abc123", "asset_abc123"]) assert.ok(isIconRef(ok), ok);
    for (const bad of ["glyph:nope", "glyph:", "../x", "javascript:alert(1)", "a b", ""]) assert.ok(!isIconRef(bad), bad);
  });
  it("drafts a description for free and clips to 280 at a sentence", () => {
    const d = draftDescription({ tagline: "Coins, /pay and a chest-menu shop", text: "Players earn coins for mob kills and spend them in a chest menu." });
    assert.match(d, /^Coins, \/pay and a chest-menu shop\. Players earn/);
    assert.equal(draftDescription({ prompt: "make me a sword that freezes enemies" }), "Sword that freezes enemies.");
    const long = clip("One sentence here. ".repeat(30));
    assert.ok(long.length <= LISTING_DESCRIPTION_MAX && long.endsWith("."));
  });
  it("drafts the dialog from saved values first, the auto-sorter second", () => {
    const fresh = draftListing({ title: "Coin Shop", sort: { primary: "economy", secondary: ["interface"] }, summary: { tagline: "Shop" } });
    assert.deepEqual([fresh.categoryId, fresh.secondaryCategoryIds], ["economy", ["interface"]]);
    const saved = draftListing({ title: "Coin Shop", sort: { primary: "economy", secondary: [] }, saved: { categoryId: "utility", description: "Mine." } });
    assert.deepEqual([saved.categoryId, saved.description], ["utility", "Mine."]);
  });
  it("monograms", () => {
    assert.equal(monogram("Frost Axe"), "FA");
    assert.equal(monogram("CoinShop"), "CS");
    assert.equal(monogram("the boss mod"), "BO");
  });
  it("project meta stores the listing (local fallback) and clears cleanly", () => {
    const p = parseProjectPatch({ title: "Coin Shop", category: "economy", secondaryCategories: ["interface", "economy"], description: "Shop.", icon: "glyph:economy" }, []);
    assert.ok(p.ok);
    if (!p.ok) return;
    const m = applyProjectPatch({}, p.patch);
    assert.deepEqual(readCyrusMeta(m), { title: "Coin Shop", category: "economy", secondaryCategories: ["interface"], categorySource: "owner", description: "Shop.", icon: "glyph:economy" });
    const auto = parseProjectPatch({ category: "worlds", categorySource: "auto" }, []);
    assert.ok(auto.ok && readCyrusMeta(applyProjectPatch({}, auto.patch)).category === "environment" && readCyrusMeta(applyProjectPatch({}, auto.patch)).categorySource === "auto");
    const clear = parseProjectPatch({ category: null, icon: null }, []);
    assert.ok(clear.ok);
    if (clear.ok) assert.deepEqual(readCyrusMeta(applyProjectPatch(m, clear.patch)), { title: "Coin Shop", description: "Shop." });
    assert.ok(!parseProjectPatch({ category: "nope" }, []).ok);
    assert.ok(!parseProjectPatch({ iconData: "data:text/html;base64,AAAA" }, []).ok);
    const icon = parseProjectPatch({ icon: "local:r1", iconData: "data:image/webp;base64,UklGRg==" }, []);
    assert.ok(icon.ok && readCyrusMeta(applyProjectPatch({}, icon.patch)).iconData?.startsWith("data:image/webp"));
  });
});

