// Cyrus v6: broad-request routing, universal categories, auto-sorter and the listing contract.
// Pure: no DB, no network. Run: tsx --test test/cyrus-route.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { GAMES } from "../lib/cyrus/data";
import { routeRequest, editDistance, namedReference, type RouteContext, type RouteDecision, type RouteProject, type RouteWorld } from "../lib/cyrus/route";
import {
  CYRUS_CATEGORIES, CYRUS_CATEGORY_IDS, autoSort, categoriesForGame, engineCategory, nearestAvailable, normalizeCategory, toCategory,
} from "../lib/cyrus/categories";
import { clip, draftDescription, draftListing, isIconRef, monogram, validateListing, LISTING_DESCRIPTION_MAX } from "../lib/cyrus/listing";
import { applyProjectPatch, parseProjectPatch, readCyrusMeta } from "../lib/cyrus/meta";

const games = GAMES.map((g) => ({ id: g.id, name: g.name, short: g.short, aliases: g.aliases, real: g.real }));
const P = (id: string, gameId: string, categoryId: string, title: string, updatedAt: number, aliases?: string[]): RouteProject => ({ id, gameId, categoryId, title, updatedAt, aliases });
const projects: RouteProject[] = [
  P("nx-frost1", "minecraft", "weapons", "Frost Axe", 100),
  P("nx-frost2", "minecraft", "weapons", "Frost Axe v2", 200),
  P("nx-shop", "minecraft", "economy", "Coin Shop", 300, ["CoinShop"]),
  P("nx-quest", "minecraft", "quests", "Daily Quest Board", 50, ["QuestBoard"]),
  P("rust-raid", "rust", "gameplay", "Smart Raid Alarms", 400),
  P("valheim-boss", "valheim", "creatures", "Bog Witch Boss", 250),
  P("terraria-yoyo", "terraria", "weapons", "Comet Shard Yoyo", 150),
];
const world: RouteWorld = { games, projects };
const empty: RouteWorld = { games, projects: [] };
const core: RouteContext = { selection: { level: "core" } };
const on = (gameId: string, category?: string): RouteContext => ({ selection: { level: category ? "category" : "game", gameId, category } });
const onMod = (modId: string): RouteContext => {
  const p = projects.find((x) => x.id === modId)!;
  return { selection: { level: "mod", gameId: p.gameId, category: String(p.categoryId), modId } };
};

type Want = Partial<Pick<RouteDecision, "intent" | "gameId" | "categoryId" | "projectId" | "unsupported" | "via">> & { clarify?: boolean; options?: string[]; minConf?: number; maxConf?: number; reason?: RegExp };

function check(text: string, ctx: RouteContext, want: Want, w: RouteWorld = world) {
  const d = routeRequest(text, ctx, w);
  const label = `${JSON.stringify(text)} -> ${JSON.stringify({ intent: d.intent, gameId: d.gameId, categoryId: d.categoryId, projectId: d.projectId, clarify: d.clarify?.options.map((o) => o.label), reason: d.reason, conf: d.confidence })}`;
  for (const k of ["intent", "gameId", "categoryId", "projectId", "unsupported", "via"] as const) if (k in want) assert.equal(d[k], want[k], `${k}: ${label}`);
  if (want.clarify !== undefined) assert.equal(!!d.clarify, want.clarify, `clarify: ${label}`);
  if (want.options) assert.deepEqual(d.clarify?.options.map((o) => o.label).slice(0, want.options.length), want.options, `options: ${label}`);
  if (want.minConf !== undefined) assert.ok(d.confidence >= want.minConf, `confidence >= ${want.minConf}: ${label}`);
  if (want.maxConf !== undefined) assert.ok(d.confidence <= want.maxConf, `confidence <= ${want.maxConf}: ${label}`);
  if (want.reason) assert.match(d.reason, want.reason, label);
  // every clarify option is itself a complete, actionable decision
  for (const o of d.clarify?.options ?? []) assert.ok(!o.decision.clarify, `option ${o.label} must not need another question: ${label}`);
  return d;
}

const CASES: [string, RouteContext, Want, RouteWorld?][] = [
  // ── creating, game named (the owner's examples first) ──
  ["make me a mod for Minecraft where creepers drop diamonds", core, { intent: "create", gameId: "minecraft", clarify: false, minConf: 0.8, reason: /^Creating a new Minecraft mod/ }],
  ["Make me a mod for minecraft where creepers drop diamonds", on("valheim"), { intent: "create", gameId: "minecraft" }],
  ["a frost sword for minecraft that slows enemies", core, { intent: "create", gameId: "minecraft", categoryId: "weapons" }],
  ["minecraft: a /home and /sethome command", core, { intent: "create", gameId: "minecraft", categoryId: "utility" }],
