      const n = tt.filter((t) => toks.some((x) => fuzzyEq(x, t))).length;
      const all = n === tt.length;
      const most = tt.length >= 3 && n >= 2 && n / tt.length >= 0.66;
      return { p, score: all ? 0.9 + Math.min(0.09, tt.length * 0.03) : most ? 0.7 : 0 };
    })
    .filter((h) => h.score > 0)
    .sort((a, b) => b.score - a.score || (b.p.updatedAt ?? 0) - (a.p.updatedAt ?? 0));
}

