"use client";

// Cyrus v6: the studio's ONLY way to read/save a mod's listing (title, category, icon, brief
// description). Thin adapter so the storage can change without touching the dialog:
//
//  - Real projects (Minecraft builds): saved on the project itself (ModBuild.cyrus on the root
//    build, PATCH /api/mod-builder/projects/:rootId; lib/cyrus/meta.ts). The studio map reads
//    the category from there, so this write always happens.
//  - THEN, when the NxLabs listing storage exists (community agent: `saveModListing`), it is also
//    sent there through COMMUNITY_BACKEND below. Until that branch is merged the backend is null
//    and the project copy is the listing (it is what the map and the post-forge dialog show).
//  - Template mods (games Cyrus doesn't compile yet) live in this browser, like the rest of their
//    data: the name/category update the local mod, the rest is kept in localStorage.
//
// MERGE NOTE (community agent): replace COMMUNITY_BACKEND with a call to your saveModListing
// (server action or route). It receives the validated ModListingInput and the project root id.

import { cyrusCategory, type CyrusCategoryId } from "./categories";
import { validateListing, type ListingCategorySource, type ListingErrors, type ModListingInput } from "./listing";
import { isRealModId, rootOfRealMod } from "./real";
import { useStore } from "./store";

export type SavedListing = Partial<ModListingInput> & { categorySource?: ListingCategorySource; iconData?: string };

export type ListingBackend = (rootId: string, input: ModListingInput) => Promise<{ ok: true } | { ok: false; error: string }>;

/** Set by the community integration (NxLabs page storage). null = project-only (see header). */
export const COMMUNITY_BACKEND: ListingBackend | null = null;

const LOCAL_KEY = "cyrus-listings-v1";

function readLocal(): Record<string, SavedListing> {
  try {
    const raw = localStorage.getItem(LOCAL_KEY);
    const j = raw ? (JSON.parse(raw) as unknown) : null;
    return j && typeof j === "object" ? (j as Record<string, SavedListing>) : {};
  } catch {
    return {};
  }
}

function writeLocal(all: Record<string, SavedListing>) {
  try { localStorage.setItem(LOCAL_KEY, JSON.stringify(all)); } catch { /* private mode / full: the mod's name+category still saved */ }
}

/** What has been saved for a mod so far (empty for a brand-new one). */
export function loadListing(modId: string): SavedListing {
  if (isRealModId(modId)) {
    const p = useStore.getState().real.projects.find((x) => x.rootId === rootOfRealMod(modId));
    if (!p) return {};
    const m = p.meta;
    return {
      ...(m.title ? { title: m.title } : {}),
      ...(m.category ? { categoryId: m.category, categorySource: m.categorySource ?? "auto" } : {}),
      ...(m.secondaryCategories ? { secondaryCategoryIds: m.secondaryCategories } : {}),
      ...(m.description !== undefined ? { description: m.description } : {}),
      ...(m.icon ? { iconAssetId: m.icon } : {}),
      ...(m.iconData ? { iconData: m.iconData } : {}),
    };
  }
  return readLocal()[modId] ?? {};
}

/** Has the owner been through the dialog for this mod (so we don't pop it again)? */
export function hasListing(modId: string): boolean {
  const l = loadListing(modId);
  return !!l.categorySource || l.description !== undefined;
}

export type SaveResult = { ok: true; value: ModListingInput } | { ok: false; error: string; errors?: ListingErrors };

/**
 * Save a listing. `source` = "owner" when the person picked/confirmed the category, "auto" when
 * they kept the auto-sorted one untouched. `iconData` = the cropped upload for icon "local:<id>".
 */
export async function saveListing(modId: string, raw: unknown, opts: { source: ListingCategorySource; iconData?: string | null }): Promise<SaveResult> {
  const v = validateListing(raw);
  if (!v.ok) return { ok: false, error: Object.values(v.errors)[0] ?? "Check the highlighted fields.", errors: v.errors };
  const input = v.value;
  const s = useStore.getState();

  if (isRealModId(modId)) {
    const rootId = rootOfRealMod(modId);
    const err = await s.patchProject(rootId, {
      title: input.title,
      category: input.categoryId,
      secondaryCategories: input.secondaryCategoryIds,
      categorySource: opts.source,
      description: input.description || null,
      icon: input.iconAssetId,
      ...(input.iconAssetId?.startsWith("local:") ? (opts.iconData !== undefined ? { iconData: opts.iconData } : {}) : { iconData: null }),
    });
    if (err) return { ok: false, error: err };
    if (COMMUNITY_BACKEND) {
      const r = await COMMUNITY_BACKEND(rootId, input).catch(() => ({ ok: false as const, error: "NxLabs didn't answer." }));
      if (!r.ok) return { ok: false, error: `Saved in your studio, but NxLabs didn't update: ${r.error}` };
    }
    return { ok: true, value: input };
  }

  // template mod: the local mod carries name + category; the rest stays in this browser
  const mine = s.userMods.find((m) => m.id === modId);
  if (!mine) return { ok: false, error: "This is an example mod. Forge your own to give it a listing." };
  useStore.setState((st) => ({ userMods: st.userMods.map((m) => (m.id === modId ? { ...m, name: input.title, category: input.categoryId } : m)) }));
  const all = readLocal();
  all[modId] = { ...input, categorySource: opts.source, ...(input.iconAssetId?.startsWith("local:") && opts.iconData ? { iconData: opts.iconData } : {}) };
  writeLocal(all);
  // keep the map focused on the mod in its (maybe new) category
  const sel = s.selection;
  if (sel.level === "mod" && sel.modId === modId && sel.category !== input.categoryId) s.select({ level: "mod", gameId: mine.gameId, category: input.categoryId, modId }, { openPanel: true });
  return { ok: true, value: input };
}

/** Saved icon for a mod as something an <img> or the glyph renderer can use. */
export function iconOf(modId: string, fallbackCategory: CyrusCategoryId): { kind: "glyph"; category: CyrusCategoryId } | { kind: "mono" } | { kind: "image"; src: string } {
  const l = loadListing(modId);
  const ref = l.iconAssetId;
  if (ref === "glyph:mono") return { kind: "mono" };
  if (ref?.startsWith("glyph:")) return { kind: "glyph", category: cyrusCategory(ref.slice(6)).id };
  if (ref?.startsWith("local:") && l.iconData) return { kind: "image", src: l.iconData };
  return { kind: "glyph", category: fallbackCategory };
}

