"use client";

import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { cyrusCategory, type CyrusCategoryId } from "@/lib/cyrus/categories";
import { monogram } from "@/lib/cyrus/listing";

/**
 * A mod's icon, always on the rounded tile: the category glyph (default), a generated monogram,
 * or an uploaded image (already cropped to the rounded shape when it was uploaded).
 */
export function ModIcon({
  icon,
  iconData,
  title,
  category,
  size = 56,
  className = "",
}: {
  icon: string | null | undefined;
  iconData?: string | null;
  title: string;
  category: CyrusCategoryId;
  size?: number;
  className?: string;
}) {
  const glyph = icon?.startsWith("glyph:") && icon !== "glyph:mono" ? cyrusCategory(icon.slice(6)) : null;
  const c = glyph ?? cyrusCategory(category);
  const radius = Math.round(size * 0.28);
  const base = `relative grid shrink-0 place-items-center overflow-hidden ${className}`;
  if (icon?.startsWith("local:") && iconData) {
    return (
      <span className={base} style={{ width: size, height: size, borderRadius: radius, boxShadow: `inset 0 0 0 1px rgb(${c.rgb} / 0.45)` }}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={iconData} alt="" className="h-full w-full object-cover" />
      </span>
    );
  }
  if (icon === "glyph:mono") {
    return (
      <span
        className={`${base} font-cy-display font-semibold text-white`}
        style={{ width: size, height: size, borderRadius: radius, fontSize: size * 0.38, background: `linear-gradient(135deg, rgb(${c.rgb}), rgb(${c.rgb} / 0.45) 60%, #312e81)`, boxShadow: `inset 0 0 0 1px rgb(255 255 255 / 0.18), 0 0 18px rgb(${c.rgb} / 0.35)` }}
        aria-hidden
      >
        {monogram(title)}
      </span>
    );
  }
  return (
    <span
      className={base}
      style={{ width: size, height: size, borderRadius: radius, fontSize: size * 0.5, color: `rgb(${c.rgb})`, background: `radial-gradient(circle at 50% 30%, rgb(${c.rgb} / 0.26), rgb(${c.rgb} / 0.08) 70%)`, boxShadow: `inset 0 0 0 1px rgb(${c.rgb} / 0.45), 0 0 18px rgb(${c.rgb} / 0.25)` }}
      aria-hidden
    >
      <CategoryIcon k={c.id} />
    </span>
  );
}

