"use client";

// Cyrus v6: the listing dialog. Opens by itself when a NEW mod finishes forging ("Name your
// mod"), and from "Edit listing" on any of your own mods. Title, category (auto-sorted, easy to
// override, up to two extra), icon (category glyph, generated monogram or an upload cropped to the
// rounded tile) and a brief description drafted for free from the build summary.
// Storage goes through lib/cyrus/listing-client.ts only.

import { useEffect, useMemo, useRef, useState } from "react";
import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { CheckIcon, CloseIcon, ImageIcon, RestoreIcon, SparkleIcon } from "@/components/cyrus/icons/ui";
import { CYRUS_CATEGORIES, CYRUS_CATEGORY, autoSort, categoriesForGame, type AutoSortResult, type CyrusCategoryId } from "@/lib/cyrus/categories";
import { LISTING_DESCRIPTION_MAX, LISTING_ICON_INLINE_MAX, LISTING_ICON_PX, LISTING_SECONDARY_MAX, LISTING_TITLE_MAX, draftDescription, draftListing, type ListingErrors } from "@/lib/cyrus/listing";
import { loadListing, saveListing } from "@/lib/cyrus/listing-client";
import { useListingUi } from "@/lib/cyrus/listing-ui";
import { isRealModId, rootOfRealMod, sortProject } from "@/lib/cyrus/real";
import { useGame, useMod, useModVersions, useStore } from "@/lib/cyrus/store";
import { ModIcon } from "./ModIcon";

/** Crop the middle square, clip it to the rounded tile, and encode small enough to keep on the project. */
async function cropIcon(file: File): Promise<string> {
  if (!/^image\/(png|jpe?g|webp|gif)$/.test(file.type)) throw new Error("Use a PNG, JPG, WebP or GIF image.");
  if (file.size > 8 * 1024 * 1024) throw new Error("That image is over 8 MB.");
  const bmp = await createImageBitmap(file);
  const side = Math.min(bmp.width, bmp.height);
  const c = document.createElement("canvas");
  c.width = c.height = LISTING_ICON_PX;
  const g = c.getContext("2d");
  if (!g) throw new Error("This browser can't crop images.");
  const r = LISTING_ICON_PX * 0.28;
  g.beginPath();
  g.roundRect(0, 0, LISTING_ICON_PX, LISTING_ICON_PX, r);
  g.clip();
  g.imageSmoothingQuality = "high";
  g.drawImage(bmp, (bmp.width - side) / 2, (bmp.height - side) / 2, side, side, 0, 0, LISTING_ICON_PX, LISTING_ICON_PX);
  bmp.close();
  for (const q of [0.9, 0.8, 0.68, 0.55, 0.42]) {
    const url = c.toDataURL("image/webp", q);
    if (url.startsWith("data:image/webp") && url.length <= LISTING_ICON_INLINE_MAX) return url;
  }
  const png = c.toDataURL("image/png");
  if (png.length <= LISTING_ICON_INLINE_MAX) return png;
  throw new Error("Couldn't make that image small enough. Try a simpler picture.");
}

const iconKey = (modId: string) => `local:${(isRealModId(modId) ? rootOfRealMod(modId) : modId).replace(/[^A-Za-z0-9_-]/g, "").slice(0, 64)}`;

export function ListingDialog() {
  const modId = useListingUi((s) => s.modId);
  if (!modId) return null;
  return <ListingDialogInner key={modId} modId={modId} />;
}

function ListingDialogInner({ modId }: { modId: string }) {
  const fresh = useListingUi((s) => s.fresh);
  const close = useListingUi((s) => s.close);
  const toast = useStore((s) => s.toast);
  const realFiles = useStore((s) => s.realFiles);
  const projects = useStore((s) => s.real.projects);
  const mod = useMod(modId);
  const game = useGame(mod?.gameId);
  const { versions, active } = useModVersions(mod);
  const project = isRealModId(modId) ? projects.find((p) => p.rootId === rootOfRealMod(modId)) : undefined;

  // What the auto-sorter says (zero API): the build's words, its commands/config and, when the
  // code is loaded, the code itself.
  const sort: AutoSortResult = useMemo(() => {
    if (!mod) return autoSort({});
    const allowed = categoriesForGame(mod.gameId);
    if (project) {
      const base = sortProject(project, { id: mod.gameId });
      const head = project.head ?? project.latest;
      const files = realFiles[head.id];
      if (!Array.isArray(files) || !files.length) return base;
      const r = project.head?.result;
      return autoSort({ title: project.title, prompt: project.builds[0]?.prompt, changes: project.builds.slice(1).map((b) => b.changeRequest), summary: [r?.summary?.tagline, r?.summary?.text].filter(Boolean).join(" "), commands: r?.commands, permissions: r?.permissions, config: r?.config, files, allowed });
    }
    return autoSort({ title: mod.name, prompt: versions[0]?.prompt ?? mod.summary, changes: versions.slice(1).map((v) => v.prompt), summary: mod.summary, files: active?.files, allowed });
  }, [mod, project, realFiles, versions, active]);

  const summarySrc = useMemo(() => {
    const s = project?.head?.result?.summary;
    if (s) return { tagline: s.tagline, text: s.text, howToUse: s.howToUse, prompt: project?.builds[0]?.prompt };
    return { tagline: mod?.summary, prompt: versions[0]?.prompt };
  }, [project, mod, versions]);

  const saved = useMemo(() => loadListing(modId), [modId]);
  const initial = useMemo(() => draftListing({ title: mod?.name ?? "", sort, saved, summary: summarySrc }), [mod?.name, sort, saved, summarySrc]);

  const [title, setTitle] = useState(initial.title);
  const [category, setCategory] = useState<CyrusCategoryId>(initial.categoryId);
  const [secondary, setSecondary] = useState<CyrusCategoryId[]>(initial.secondaryCategoryIds);
  const [icon, setIcon] = useState<string | null>(initial.iconAssetId);
  const [iconData, setIconData] = useState<string | null>(saved.iconData ?? null);
  const [description, setDescription] = useState(initial.description);
  const [touchedCat, setTouchedCat] = useState(saved.categorySource === "owner");
  const [showMoreCats, setShowMoreCats] = useState(initial.secondaryCategoryIds.length > 0);
  const [errors, setErrors] = useState<ListingErrors>({});
  const [busy, setBusy] = useState(false);
  const [iconErr, setIconErr] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const titleRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const t = window.setTimeout(() => titleRef.current?.select(), 60);
    return () => window.clearTimeout(t);
  }, []);

  if (!mod || !game) return null;
  const owned = !!mod.real || useStore.getState().userMods.some((m) => m.id === mod.id);
  const allowed = categoriesForGame(mod.gameId);
  const autoChosen = !touchedCat && category === sort.primary;
  const cat = CYRUS_CATEGORY[category];
  const evidence = (sort.why[sort.primary] ?? []).slice(0, 3).map((w) => w.replace(/^(\w+): /, "$1 “") + "”").join(", ");

  const pickPrimary = (c: CyrusCategoryId) => {
    setCategory(c);
    setTouchedCat(true);
    setSecondary((s) => s.filter((x) => x !== c));
  };
  const toggleSecondary = (c: CyrusCategoryId) =>
    setSecondary((s) => (s.includes(c) ? s.filter((x) => x !== c) : s.length >= LISTING_SECONDARY_MAX ? [...s.slice(1), c] : [...s, c]));

  const onUpload = async (f: File | undefined) => {
    if (!f) return;
    setIconErr(null);
    try {
      const url = await cropIcon(f);
      setIconData(url);
      setIcon(iconKey(modId));
    } catch (e) {
      setIconErr((e as Error).message);
    }
  };

  const save = async () => {
    if (busy) return;
    setBusy(true);
    setErrors({});
    const r = await saveListing(modId, { title, categoryId: category, secondaryCategoryIds: secondary, iconAssetId: icon, description }, { source: autoChosen && saved.categorySource !== "owner" ? "auto" : "owner", iconData: icon?.startsWith("local:") ? iconData : null });
    setBusy(false);
    if (!r.ok) {
      setErrors(r.errors ?? {});
      toast({ tone: "error", title: "Couldn't save the listing", body: r.error });
      return;
    }
    toast({ tone: "success", title: `${r.value.title} saved`, body: `${CYRUS_CATEGORY[r.value.categoryId].label}${r.value.secondaryCategoryIds.length ? ` + ${r.value.secondaryCategoryIds.map((c) => CYRUS_CATEGORY[c].label).join(", ")}` : ""}`, rgb: CYRUS_CATEGORY[r.value.categoryId].rgb });
    close();
  };

  const iconChoices: { ref: string | null; label: string }[] = [
    { ref: null, label: "Category glyph" },
    { ref: "glyph:mono", label: "Monogram" },
    ...(iconData ? [{ ref: iconKey(modId), label: "Your image" }] : []),
  ];

  return (
    <div
      className="animate-fade fixed inset-0 z-[60] flex items-end justify-center bg-[rgb(3_3_10/0.6)] backdrop-blur-[6px] cy-light:bg-[rgb(91_33_182/0.1)] sm:items-start sm:overflow-y-auto sm:px-3 sm:py-[6cqh]"
      onPointerDown={() => !busy && close()}
      data-testid="cyrus-listing-dialog"
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="cy-listing-title"
        className="animate-rise relative flex max-h-[92cqh] w-full max-w-[620px] flex-col overflow-hidden rounded-t-3xl border border-cy-line-2 sm:max-h-none sm:rounded-3xl"
        style={{ background: "var(--solid)", boxShadow: "var(--panel-shadow)" }}
        onPointerDown={(e) => e.stopPropagation()}
        onKeyDown={(e) => {
          if (e.key === "Escape" && !busy) close();
          if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) void save();
        }}
      >
        <div className="h-[3px] w-full shrink-0" style={{ background: `linear-gradient(90deg, rgb(${cat.rgb}), #8b5cf6 55%, #06b6d4)` }} />
        <div className="flex items-start gap-4 border-b border-cy-line px-5 pb-4 pt-5 sm:px-6">
          <ModIcon icon={icon} iconData={iconData} title={title || mod.name} category={category} size={64} />
          <div className="min-w-0 flex-1">
            <div className="flex items-start gap-2">
              <div className="min-w-0">
                <p className="text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">{fresh ? `${game.name} · just forged` : `${game.name} · listing`}</p>
                <h2 id="cy-listing-title" className="font-cy-display text-[19px] font-semibold leading-tight text-cy-ink">
                  {fresh ? "Name your mod" : "Edit listing"}
                </h2>
              </div>
              <button type="button" onClick={close} disabled={busy} className="cy5-btn-ghost ml-auto h-8 w-8 shrink-0 text-cy-muted" aria-label="Close">
                <CloseIcon />
              </button>
            </div>
            <p className="mt-1 text-[12.5px] leading-relaxed text-cy-ink-2">
              How it shows on your map{mod.real ? ", in your servers' mod list and on its NxLabs page when you publish it" : ""}. You can change this any time.
            </p>
          </div>
        </div>

        <div className="min-h-0 flex-1 space-y-5 overflow-y-auto px-5 py-5 sm:px-6">
          {!owned && (
            <p className="rounded-xl border border-cy-line bg-[rgb(var(--glow)/0.06)] px-3 py-2 text-[12px] text-cy-ink-2">
              This is an example mod. Forge your own to give it a listing.
            </p>
          )}

          {/* Title */}
          <label className="block">
            <span className="mb-1.5 flex items-center text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">
              Title
              <span className={`ml-auto normal-case tracking-normal tabular-nums ${title.length > LISTING_TITLE_MAX ? "text-rose-400" : "text-cy-faint"}`}>
                {title.length}/{LISTING_TITLE_MAX}
              </span>
            </span>
            <input
              ref={titleRef}
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              maxLength={LISTING_TITLE_MAX + 10}
              aria-invalid={!!errors.title}
              className="h-11 w-full rounded-xl border bg-[rgb(var(--glow)/0.05)] px-3.5 text-[15px] text-cy-ink outline-none transition focus:border-cy-accent focus:bg-[rgb(var(--glow)/0.08)]"
              style={{ borderColor: errors.title ? "rgb(251 113 133)" : "var(--line-2)" }}
              placeholder="Frost Axe"
            />
            {errors.title && <span className="mt-1 block text-[11.5px] text-rose-400">{errors.title}</span>}
          </label>

          {/* Category */}
          <section aria-labelledby="cy-listing-cat">
            <h3 id="cy-listing-cat" className="mb-1.5 flex flex-wrap items-center gap-2 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">
              Category
              {autoChosen && sort.confident && (
                <span className="inline-flex items-center gap-1 rounded-full bg-[rgb(var(--glow)/0.12)] px-2 py-0.5 text-[10.5px] normal-case tracking-normal text-cy-accent-ink" title={evidence ? `Sorted from ${evidence}` : undefined}>
                  <SparkleIcon /> Auto-sorted
                </span>
              )}
              {!touchedCat && saved.categorySource === "owner" && <span className="normal-case tracking-normal text-cy-faint">your pick</span>}
            </h3>
            {autoChosen && !sort.confident && (
              <p className="mb-2 rounded-xl border border-amber-400/30 bg-amber-400/10 px-3 py-2 text-[12px] text-cy-ink-2">
                Cyrus wasn&apos;t sure where this one goes. Pick the closest category.
              </p>
            )}
            {autoChosen && sort.confident && evidence && <p className="mb-2 text-[11.5px] text-cy-faint">Sorted from {evidence}. Wrong? Pick another.</p>}
            <div className="grid grid-cols-2 gap-1.5 sm:grid-cols-4" role="radiogroup" aria-label="Category">
              {CYRUS_CATEGORIES.map((c) => {
                const on = c.id === category;
                const off = !allowed.includes(c.id);
                return (
                  <button
                    key={c.id}
                    type="button"
                    role="radio"
                    aria-checked={on}
                    disabled={off}
                    onClick={() => pickPrimary(c.id)}
                    title={off ? `${game.name} mods can't do this yet` : c.blurb}
                    className="flex min-w-0 items-center gap-1.5 rounded-xl border px-2 py-1.5 text-left text-[12px] transition disabled:cursor-not-allowed disabled:opacity-35"
                    style={{
                      color: on ? "var(--ink)" : "var(--ink-2)",
                      borderColor: on ? `rgb(${c.rgb} / 0.75)` : "var(--line)",
                      background: on ? `rgb(${c.rgb} / 0.14)` : "rgb(var(--glow) / 0.03)",
                      boxShadow: on ? `0 0 16px rgb(${c.rgb} / 0.22)` : undefined,
                    }}
                  >
                    <span className="shrink-0 text-[15px]" style={{ color: `rgb(${c.rgb})` }}>
                      <CategoryIcon k={c.id} />
                    </span>
                    <span className="truncate">{c.label}</span>
                    {on && <CheckIcon className="ml-auto shrink-0 text-[12px]" />}
                  </button>
                );
              })}
            </div>
            {errors.categoryId && <span className="mt-1 block text-[11.5px] text-rose-400">{errors.categoryId}</span>}

            <div className="mt-3">
              {!showMoreCats ? (
                <button type="button" onClick={() => setShowMoreCats(true)} className="text-[12px] font-medium text-cy-accent-ink hover:underline">
                  + Also fits another category
                </button>
              ) : (
                <>
                  <p className="mb-1.5 text-[11.5px] text-cy-muted">
                    Also fits <span className="text-cy-faint">(optional, up to {LISTING_SECONDARY_MAX}: helps people find it in NxLabs)</span>
                  </p>
                  <div className="flex flex-wrap gap-1.5">
                    {CYRUS_CATEGORIES.filter((c) => c.id !== category && allowed.includes(c.id)).map((c) => {
                      const on = secondary.includes(c.id);
                      return (
                        <button
                          key={c.id}
                          type="button"
                          aria-pressed={on}
                          onClick={() => toggleSecondary(c.id)}
                          className="flex items-center gap-1 rounded-full border py-0.5 pl-1.5 pr-2 text-[11.5px] transition"
                          style={{ color: on ? "var(--ink)" : "var(--muted)", borderColor: on ? `rgb(${c.rgb} / 0.7)` : "var(--line)", background: on ? `rgb(${c.rgb} / 0.12)` : undefined }}
                        >
                          <span className="text-[12px]" style={{ color: `rgb(${c.rgb})` }}>
                            <CategoryIcon k={c.id} />
                          </span>
                          {c.label}
                        </button>
                      );
                    })}
                  </div>
                </>
              )}
            </div>
          </section>

          {/* Icon */}
          <section aria-labelledby="cy-listing-icon">
            <h3 id="cy-listing-icon" className="mb-1.5 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">Icon</h3>
            <div className="flex flex-wrap items-center gap-2">
              {iconChoices.map((o) => {
                const on = (o.ref ?? null) === (icon ?? null) || (!!o.ref?.startsWith("local:") && !!icon?.startsWith("local:"));
                return (
                  <button
                    key={o.label}
                    type="button"
                    onClick={() => setIcon(o.ref)}
                    aria-pressed={on}
                    title={o.label}
                    className="rounded-[18px] p-1 transition"
                    style={{ boxShadow: on ? `0 0 0 2px rgb(${cat.rgb})` : "0 0 0 1px var(--line)" }}
                  >
                    <ModIcon icon={o.ref} iconData={iconData} title={title || mod.name} category={category} size={44} />
                    <span className="sr-only">{o.label}</span>
                  </button>
                );
              })}
              <input ref={fileRef} type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden onChange={(e) => { void onUpload(e.target.files?.[0]); e.target.value = ""; }} />
              <button type="button" onClick={() => fileRef.current?.click()} className="cy5-btn-ghost inline-flex h-[52px] items-center gap-1.5 rounded-[18px] border border-dashed border-cy-line-2 px-3 text-[12px] text-cy-ink-2">
                <ImageIcon /> Upload
              </button>
              <details className="relative">
                <summary className="cy5-btn-ghost inline-flex h-[52px] cursor-pointer list-none items-center rounded-[18px] px-3 text-[12px] text-cy-ink-2">Other glyphs</summary>
                <div className="absolute left-0 top-[58px] z-10 grid w-[244px] grid-cols-6 gap-1 rounded-2xl border border-cy-line-2 p-2" style={{ background: "var(--solid)", boxShadow: "var(--panel-shadow)" }}>
                  {CYRUS_CATEGORIES.map((c) => (
                    <button key={c.id} type="button" title={c.label} onClick={(e) => { setIcon(`glyph:${c.id}`); (e.currentTarget.closest("details") as HTMLDetailsElement | null)?.removeAttribute("open"); }} className="rounded-xl p-0.5 hover:bg-[rgb(var(--glow)/0.1)]">
                      <ModIcon icon={`glyph:${c.id}`} title="" category={c.id} size={32} />
                      <span className="sr-only">{c.label}</span>
                    </button>
                  ))}
                </div>
              </details>
            </div>
            <p className="mt-1.5 text-[11.5px] text-cy-faint">Uploads are cropped to the rounded tile (square middle of the image).</p>
            {(iconErr || errors.iconAssetId) && <span className="mt-1 block text-[11.5px] text-rose-400">{iconErr || errors.iconAssetId}</span>}
          </section>

