              <button type="button" onClick={() => setDescription(draftDescription(summarySrc))} className="inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[10.5px] normal-case tracking-normal text-cy-accent-ink hover:bg-[rgb(var(--glow)/0.1)]" title="Draft again from the build summary (free, no tokens)">
                <RestoreIcon /> Redraft
              </button>
              <span className={`ml-auto normal-case tracking-normal tabular-nums ${description.length > LISTING_DESCRIPTION_MAX ? "text-rose-400" : "text-cy-faint"}`}>
                {description.length}/{LISTING_DESCRIPTION_MAX}
              </span>
            </span>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              aria-invalid={!!errors.description}
              placeholder="One or two sentences: what it does and why someone would install it."
              className="w-full resize-none rounded-xl border bg-[rgb(var(--glow)/0.05)] px-3.5 py-2.5 text-[13.5px] leading-relaxed text-cy-ink outline-none transition focus:border-cy-accent"
              style={{ borderColor: errors.description ? "rgb(251 113 133)" : "var(--line-2)" }}
            />
            <span className="mt-1 block text-[11.5px] text-cy-faint">{errors.description ?? "Drafted from what Cyrus reported about the build. No tokens spent."}</span>
          </label>
        </div>

        <div className="flex shrink-0 items-center gap-2 border-t border-cy-line px-5 py-3.5 sm:px-6">
          <span className="hidden text-[11px] text-cy-faint sm:inline">
            <span className="cy5-kbd">Ctrl</span>+<span className="cy5-kbd">Enter</span> to save
          </span>
          <button type="button" onClick={close} disabled={busy} className="cy5-btn-ghost ml-auto h-10 px-3.5 text-[13px]">
