"use client";

// Cyrus v6: the dock's side of broad-request routing. `useRouteDecision` runs the pure router
// (lib/cyrus/route.ts) on every keystroke against the account's own mods; `runDecision` acts on
// a decision: it moves the selection (the camera glides, the branch lights up, the preview
// opens) and then forges, or opens the right view for questions, installs and "show me".
// No API calls are made to decide anything.

import { useMemo } from "react";
import { projectTitle, spaced } from "@/lib/cyrus/projects";
import { routeRequest, type RouteDecision, type RouteProject, type RouteWorld } from "@/lib/cyrus/route";
import { forge, type ForgeImage } from "@/lib/cyrus/forge";
import { fx } from "@/lib/cyrus/fx";
import { categoriesForGame } from "@/lib/cyrus/categories";
import { CORE_ID, findMod, getGame, useGames, useStore, type PanelTab } from "@/lib/cyrus/store";

/** The preview tab that explains a mod. Studio-ui adds a dedicated "explain" tab; switch to it on merge. */
export const EXPLAIN_TAB: PanelTab = "notes";

/** The account's own mods as the router sees them (real projects + local template mods; never idea seeds or examples). */
export function useRouteWorld(): RouteWorld {
  const games = useGames();
  const realMods = useStore((s) => s.real.mods);
  const projects = useStore((s) => s.real.projects);
  const userMods = useStore((s) => s.userMods);
  return useMemo(() => {
    const byRoot = new Map(projects.map((p) => [p.rootId, p]));
    const list: RouteProject[] = [
      ...realMods.map((m) => {
        const p = m.real ? byRoot.get(m.real.rootId) : undefined;
        const names = p ? [p.head?.pluginName, p.latest.pluginName].filter((x): x is string => !!x).map(spaced) : [];
        const auto = p ? projectTitle({}, p.head, p.latest) : null;
        return { id: m.id, gameId: m.gameId, categoryId: m.category, title: m.name, aliases: [...new Set([...names, ...(auto && auto !== m.name ? [auto] : [])])], updatedAt: m.createdAt };
      }),
      ...userMods.map((m) => ({ id: m.id, gameId: m.gameId, categoryId: m.category, title: m.name, updatedAt: m.createdAt })),
    ];
    return { games: games.map((g) => ({ id: g.id, name: g.name, short: g.short, aliases: g.aliases, real: g.real })), projects: list };
  }, [games, realMods, projects, userMods]);
}

export function useRouteDecision(text: string): RouteDecision | null {
  const world = useRouteWorld();
  const selection = useStore((s) => s.selection);
  return useMemo(() => (text.trim() ? routeRequest(text, { selection }, world) : null), [text, selection, world]);
}

/** Decide on submit (fresh state, no React). */
export function decideNow(text: string, world: RouteWorld): RouteDecision {
  return routeRequest(text, { selection: useStore.getState().selection }, world);
}

/** Is acting on this decision a REAL build (tokens, a compiled plugin) rather than a template preview? */
export function isRealDecision(d: RouteDecision | null): boolean {
  if (!d) return false;
  if (d.projectId) {
    const m = findMod(d.projectId);
    return !!m?.real || !!getGame(m?.gameId)?.real;
  }
  return !!getGame(d.gameId ?? undefined)?.real;
}

export type RunResult = "forged" | "navigated" | "needs-input";

/**
 * Act on a decision. Forging intents move the selection first (forge() reads it), so the camera
 * flies to the target branch while the request goes out.
 */
export function runDecision(d: RouteDecision, text: string, images: ForgeImage[]): RunResult {
  const s = useStore.getState();
  const path = (gameId: string, catId?: string | null, modId?: string) => [CORE_ID, gameId, ...(catId ? [`${gameId}:${catId}`] : []), ...(modId ? [modId] : [])];
  const glow = (ids: string[], rgb?: string) => fx.packets(ids, 3, { rgb: rgb ?? "167 139 250", speed: 1.5, size: 1.3, gap: 0.1 });

  switch (d.intent) {
    case "create": {
      if (!d.gameId) return "needs-input";
      const game = getGame(d.gameId);
      const cat = d.categoryId ?? game?.categories[0] ?? categoriesForGame(d.gameId)[0];
      s.select({ level: "category", gameId: d.gameId, category: cat }, { openPanel: false });
      glow(path(d.gameId, cat), game?.rgb);
      void forge(text, images);
      return "forged";
    }
    case "refine":
    case "fix": {
      const mod = findMod(d.projectId);
      if (!mod) return "needs-input";
      s.select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true });
      glow(path(mod.gameId, mod.category, mod.id), getGame(mod.gameId)?.rgb);
      void forge(text, images);
      return "forged";
    }
    case "explain":
    case "install": {
      const mod = findMod(d.projectId);
      if (!mod) return "needs-input";
      s.select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true });
      glow(path(mod.gameId, mod.category, mod.id), getGame(mod.gameId)?.rgb);
      if (d.intent === "explain") s.setPanelTab(EXPLAIN_TAB);
      else {
        const built = mod.real && !mod.real.running && !!mod.real.headBuildId;
        if (built) window.setTimeout(() => window.dispatchEvent(new CustomEvent("cyrus:install", { detail: { modId: mod.id } })), 350);
        else s.toast({ tone: "info", title: mod.real ? "Nothing to install yet" : "Template preview", body: mod.real ? "This mod has no version that built yet." : `Cyrus doesn't compile ${getGame(mod.gameId)?.name ?? "this game"} mods yet, so there's nothing to install. Download the source from the panel.` });
      }
      return "navigated";
    }
    case "browse": {
      if (d.gameId) {
        s.select({ level: "game", gameId: d.gameId }, { openPanel: true });
        glow(path(d.gameId), getGame(d.gameId)?.rgb);
      } else {
        s.select({ level: "core" }, { openPanel: true });
        fx.ripple(true);
      }
      return "navigated";
    }
    default:
      return "needs-input";
  }
}

