// Cyrus v6: give every existing Cyrus project a stored universal category (one-off migration helper).
//
// For each project (a root ModBuild and its versions) whose root has NO saved category yet, run the
// same zero-API auto-sorter the studio uses (lib/cyrus/real.ts sortProject) and store
// { category, secondaryCategories, categorySource: "auto" } in the root build's `cyrus` JSON.
// Owner picks ("owner") and already-sorted projects are never touched. Nothing else changes.
//
//   npx tsx scripts/cyrus-categorize-projects.ts            # DRY RUN: prints what it would do
//   npx tsx scripts/cyrus-categorize-projects.ts --apply    # writes (throwaway DBs only, see below)
//   ... --user <userId>                                     # one account only
//
// SAFETY: --apply refuses any database that isn't a node-2 throwaway (127.0.0.1:5433/wt_*) unless
// CYRUS_MIGRATE_ALLOW_PROD=yes-the-owner-approved is set. Production needs the owner's explicit
// go-ahead first (it writes customer rows). It only ever UPDATEs ModBuild.cyrus on root builds.
import type { Prisma } from "@prisma/client";
import { db } from "../lib/db";
import { toView } from "../lib/modbuilder/store";
import { readCyrusMeta } from "../lib/cyrus/meta";
import { groupProjects } from "../lib/cyrus/projects";
import { sortProject } from "../lib/cyrus/real";
import { GAMES } from "../lib/cyrus/data";

const REAL_GAME = GAMES.find((g) => g.real) ?? GAMES[0];

async function main() {
  const args = process.argv.slice(2);
  const apply = args.includes("--apply");
  const userIdx = args.indexOf("--user");
  const onlyUser = userIdx >= 0 ? args[userIdx + 1] : null;
  const url = process.env.DATABASE_URL ?? "";
  const throwaway = /@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/i.test(url);
  if (apply && !throwaway && process.env.CYRUS_MIGRATE_ALLOW_PROD !== "yes-the-owner-approved") {
    throw new Error("refusing to --apply: not a node-2 throwaway DB (set CYRUS_MIGRATE_ALLOW_PROD only with the owner's approval)");
