// THROWAWAY Playwright run ON node-2 (devhost run). NOT COMMITTED. Real server-rendered
// /dashboard/cyrus against the node-2 dev server + the local build-service stand-in.
// BASE=http://127.0.0.1:<port> OUT=dir  ONLY=dark-1440,light-390  FRESH=1 (also do a real forge)
import { chromium } from "playwright";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const BASE = process.env.BASE;
const OUT = process.env.OUT || "verify-rt/shots";
const ONLY = (process.env.ONLY || "").split(",").filter(Boolean);
const { token } = JSON.parse(readFileSync(".next.cyrus-session.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const log = [];
const note = (...a) => { const l = a.join(" "); log.push(l); console.log(l); };

const browser = await chromium.launch({ args: ["--disable-dev-shm-usage", "--use-gl=swiftshader", "--enable-webgl", "--ignore-gpu-blocklist"] });
async function ctx(w, theme) {
  const mobile = w < 600;
  const c = await browser.newContext({ viewport: { width: w, height: mobile ? 844 : 900 }, deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile });
  const host = new URL(BASE).hostname;
  await c.addCookies([{ name: "nxeon_session", value: token, domain: host, path: "/" }, { name: "nxeon_authed", value: "1", domain: host, path: "/" }]);
  await c.addInitScript((t) => {
    try {
      localStorage.setItem("nx-theme", t);
      for (const k of ["nx-whatsnew-seen", "nx-tour-done", "heard-about-us-dismissed", "promo-trial-dismissed"]) localStorage.setItem(k, "1");
    } catch {}
  }, theme);
  return c;
}
const shot = async (page, name, wait = 900) => {
  await page.waitForTimeout(wait);
  await page.screenshot({ path: `${OUT}/${name}.png`, timeout: 180000 });
  note("shot", name);
};
async function closePopups(page) {
  for (const name of ["Got it", "Close", "Not now", "Skip", "Dismiss"]) {
    const b = page.getByRole("button", { name, exact: true });
    if ((await b.count()) && (await b.first().isVisible().catch(() => false))) await b.first().click().catch(() => {});
  }
}
async function typeIn(page, text) {
  const ta = page.getByLabel("Describe your mod");
  await ta.click();
  await ta.fill("");
  await ta.type(text, { delay: 4 });
  await page.waitForTimeout(400);
}
async function chip(page) {
  const c = page.getByTestId("cyrus-route-chip");
  if (!(await c.count())) return null;
  return { intent: await c.getAttribute("data-intent"), game: await c.getAttribute("data-game"), category: await c.getAttribute("data-category"), project: await c.getAttribute("data-project"), text: (await c.innerText()).replace(/\s+/g, " ").slice(0, 200) };
}
const noSideScroll = async (page) => page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1);

for (const [theme, w] of [["dark", 1440], ["light", 1440], ["dark", 390], ["light", 390]]) {
  const key = `${theme}-${w}`;
  if (ONLY.length && !ONLY.includes(key)) continue;
  const c = await ctx(w, theme);
  const page = await c.newPage();
  page.on("pageerror", (e) => note("PAGEERROR", key, e.message));
  page.on("console", (m) => { if (m.type() === "error") note("CONSOLE", key, m.text().slice(0, 300)); });
  const r = await page.goto(BASE + "/dashboard/cyrus", { waitUntil: "domcontentloaded", timeout: 300000 });
  note("GET /dashboard/cyrus", key, r?.status());
  await page.waitForSelector(".cyrus-root .stage", { timeout: 300000 }).catch((e) => note("no stage", e.message));
  await page.waitForTimeout(7000);
  await closePopups(page);

  // 1. nothing selected, a broad create request
  await typeIn(page, "make me a mod for Minecraft where creepers drop diamonds");
  note("chip", key, JSON.stringify(await chip(page)));
  await shot(page, `${key}-1-route-create-from-core`);

  // 2. "my frost axe mod" matches two projects -> one-tap clarify
  await typeIn(page, "work on my frost axe mod and fix the cooldown");
  note("chip", key, JSON.stringify(await chip(page)));
  await shot(page, `${key}-2-route-clarify`);

  // 3. unsupported game
  await typeIn(page, "make me a skyrim mod with dragon shouts");
  note("chip", key, JSON.stringify(await chip(page)));
  await shot(page, `${key}-3-route-unsupported`);

  // 4. a refine jump: pick "Frost Axe" from the clarify chips -> camera flies, panel opens, forge starts
  await typeIn(page, "work on my frost axe mod and fix the cooldown");
  const opt = page.getByRole("button", { name: /^Frost Axe(?! v2)/ }).first();
  if (await opt.count()) {
    await opt.click();
    await page.waitForTimeout(2600);
    note("selection after refine jump", key, await page.evaluate(() => document.querySelector("[aria-label='Close panel']") ? "panel open" : "no panel"));
    await shot(page, `${key}-4-refine-jump`, 300);
    const stop = page.getByRole("button", { name: "Stop forging" });
    if (await stop.count()) { await stop.click(); note("stopped forge", key); }
    await page.waitForTimeout(2500);
  } else note("NO Frost Axe option", key);

  // 5. explain from anywhere, then Edit listing on that mod
  await page.keyboard.press("Escape");
  await typeIn(page, "what does my coin shop do?");
  note("chip", key, JSON.stringify(await chip(page)));
  await page.keyboard.press("Enter");
  await page.waitForTimeout(2500);
  await shot(page, `${key}-5-explain-jump`, 300);
  const edit = page.getByRole("button", { name: "Edit listing" });
  if (await edit.count()) {
    await edit.first().click();
    await page.waitForSelector("[data-testid=cyrus-listing-dialog]", { timeout: 15000 });
    await shot(page, `${key}-6-listing-dialog`);
    note("dialog side-scroll ok", key, await noSideScroll(page));
    if (w < 600) { await page.getByRole("dialog").evaluate((el) => el.querySelector(".overflow-y-auto")?.scrollTo(0, 9999)); await shot(page, `${key}-6b-listing-dialog-bottom`); }
    // owner override: pick Utility, save
    if (theme === "dark" && w === 1440) {
      await page.getByRole("radio", { name: /Utility & QoL/ }).click();
      await page.getByRole("button", { name: /Monogram/ }).click().catch(() => {});
      await shot(page, `${key}-7-listing-override`, 300);
      await page.getByRole("button", { name: /Save listing/ }).click();
      await page.waitForTimeout(2500);
      await shot(page, `${key}-8-after-save`, 300);
    } else {
      await page.getByRole("button", { name: "Cancel" }).click();
    }
  } else note("NO Edit listing button", key);
  note("page side-scroll ok", key, await noSideScroll(page));

  // 6. a real forge from the core -> the fresh "Name your mod" dialog when it builds
  if (process.env.FRESH && theme === "dark" && w === 1440) {
    await page.keyboard.press("Escape");
    await page.getByRole("button", { name: "Clear context" }).click().catch(() => {});
    await typeIn(page, "make me a mod for Minecraft where creepers drop diamonds");
    await page.keyboard.press("Enter");
    await page.waitForTimeout(3000);
    await shot(page, `${key}-9-forging`, 300);
    const ok = await page.waitForSelector("[data-testid=cyrus-listing-dialog]", { timeout: 120000 }).then(() => true, () => false);
    note("fresh dialog opened", ok);
    await shot(page, `${key}-10-listing-fresh`);
  }
  await c.close();
}
writeFileSync(`${OUT}/log.txt`, log.join("\n"));
